window.PAGESDOC_INDEX = [{"p":"الديوان (Diwan ERP)","g":"الرئيسية","u":"index.html","h":"الديوان (Diwan ERP)","t":"نظام تخطيط موارد مؤسسات عربي يعمل كخدمة سحابية (SaaS) متعددة المنشآت: لكل منشأة نطاق فرعي خاص وبيانات معزولة تماماً، مع محاسبة متكاملة، ومبيعات ومشتريات ومستودعات، وفوترة إلكترونية متوافقة مع هيئة الزكاة والضريبة والجمارك (المرحلتان)، ومقاولات، وموارد بشرية ورواتب وفق نظام العمل السعودي."},{"p":"الديوان (Diwan ERP)","g":"الرئيسية","u":"index.html#التثبيت-مجاني","h":"التثبيت (مجاني)","t":"النظام متاح مجاناً، ويمكن تثبيته دون أي خبرة تقنية، وعلى جهاز لا يحتوي أي برنامج مسبق. ابدأ من دليل التثبيت، أو اذهب مباشرة إلى دليل جهازك: الجهاز طريقة التثبيت الدليل ويندوز 10/11 نزّل Diwan-Setup.bat وانقر عليه نقراً مزدوجاً تثبيت «الديوان» على ويندوز ماك سطر واحد في Terminal تثبيت «الديوان» على ماك لينكس (Ubuntu / Mint / Debian) سطر واحد في الطرفية تثبيت «الديوان» على لينكس (Ubuntu / Mint / Debian) خادم على الإنترنت (عدة منشآت بنطاقات فرعية) سطر واحد على الخادم دليل إعداد خادم «الديوان» من الصفر على الجهاز الشخصي يعمل النظام لمنشأتك، وتفتحه بقية أجهزة المكتب والجوالات من الشبكة نفسها. يتحدّث تلقائياً كل ليلة، ويأخذ نسخة احتياطية مشفّرة يومياً."},{"p":"الديوان (Diwan ERP)","g":"الرئيسية","u":"index.html#الوحدات","h":"الوحدات","t":"الوحدة أبرز ما تشمله المحاسبة شجرة حسابات متوافقة مع SOCPA، قيود مزدوجة إلزامية التوازن، سنوات وفترات مالية، مراكز تكلفة، ميزان مراجعة وقوائم مالية وتدفقات نقدية، أعمار الديون، إقرار ضريبة القيمة المضافة، الأصول الثابتة والإهلاك، الشيكات، التسويات البنكية، الموازنات، القيود المتكررة، إقفال السنة المبيعات عروض أسعار ← أوامر بيع (باعتماد) ← أذونات تسليم ← فواتير ضريبية/مبسطة، مرتجعات بالأصناف، إشعارات دائنة ومدينة، قوائم أسعار وشرائح كميات، حد ائتماني، توزيع سندات القبض المشتريات طلبات شراء ← أوامر شراء (باعتماد) ← استلام بضاعة GRN ← فاتورة مورد بمطابقة ثلاثية، مرتجعات، تكاليف إضافية (شحن وجمارك) المستودعات سجل حركات مخزنية، متوسط مرجح أو FIFO، وحدات متعددة، دفعات وتواريخ انتهاء، أرقام تسلسلية"},{"p":"الديوان (Diwan ERP)","g":"الرئيسية","u":"index.html#إرسال-المستندات-للعملاء","h":"إرسال المستندات للعملاء","t":"PDF رسمي للفاتورة والإشعار الدائن وعرض السعر والمستخلص وكشف الحساب: يتبع ألوان قالب الطباعة وشعار المنشأة. يتضمن المبلغ كتابةً ورمز QR. فواتير الزكاة بصيغة PDF/A-3 مع ملف XML مضمّن. إرسال للعميل: بريد إلكتروني: المستند مرفق PDF، والرد يصل لبريد المنشأة. واتساب: رابط PDF موقّع ومؤقت. كل عملية إرسال تُسجَّل في سجل الإرسال. رابط كشف حساب للعميل: يفتح بلا تسجيل دخول، وفيه الرصيد والفواتير وتنزيلها. الرابط موقّع ومقيّد بالعميل نفسه، وينتهي بعد المدة المحددة في DOCUMENT_LINK_DAYS. ما يحتاج ضبطاً في .env: إعدادات البريد (MAIL_*). تشغيل الطابور (queue:work)."},{"p":"الديوان (Diwan ERP)","g":"الرئيسية","u":"index.html#العملات-المتعددة-والتاريخ-الهجري","h":"العملات المتعددة والتاريخ الهجري","t":""},{"p":"الديوان (Diwan ERP)","g":"الرئيسية","u":"index.html#العملات-المتعددة","h":"العملات المتعددة","t":"أين تُستخدم: فواتير البيع والشراء وسندات القبض والصرف. تُعرَّف العملات وأسعار صرفها المؤرخة من «الإعدادات ← العملات وأسعار الصرف». سعر الصرف: يأخذ المستند آخر سعر في تاريخه، ويمكن تعديله يدوياً في المستند نفسه. القيود المحاسبية: تُرحَّل دائماً بالعملة الأساسية. تُقيَّم البضاعة المستوردة بالريال بسعر فاتورة الشراء. عند السداد بسعر مختلف عن سعر الفاتورة، يُرحَّل فرق العملة المحقق تلقائياً. المرتجعات والإشعارات: تتبع عملة الفاتورة الأصلية وسعرها. الفوترة الإلكترونية: فاتورة الزكاة بعملة أجنبية تُبلَّغ بعملتها، مع إجمالي الضريبة بالريال كما تشترط الهيئة. عروض الأسعار وأوامر البيع والشراء: ما زالت بالعملة الأساسية."},{"p":"الديوان (Diwan ERP)","g":"الرئيسية","u":"index.html#التاريخ-الهجري","h":"التاريخ الهجري","t":"مكان الظهور: يظهر هجري أم القرى بجانب تواريخ انتهاء الهوية والإقامة والجواز والوثائق وخطابات الضمان، وفي ملفات PDF للمستندات. إيقافه: يمكن إيقافه في ملفات PDF من الإعدادات."},{"p":"الديوان (Diwan ERP)","g":"الرئيسية","u":"index.html#الفواتير-الدورية-ولوحات-القيادة","h":"الفواتير الدورية ولوحات القيادة","t":""},{"p":"الديوان (Diwan ERP)","g":"الرئيسية","u":"index.html#الفواتير-الدورية","h":"الفواتير الدورية","t":"الاستخدام: عقود الخدمات، مثل الإيجار والصيانة والاشتراكات. الإصدار: تُصدر الفاتورة تلقائياً كل شهر أو ربع سنة أو سنة، عبر المجدول (erp:accounting-schedules recurring). الإرسال: يمكن إرسالها للعميل بالبريد عند إصدارها. منع التكرار: كل فترة تُصدر مرة واحدة فقط، حتى لو شُغّل الأمر أكثر من مرة. وإذا توقف المجدول، تُستكمل الفترات الفائتة عند تشغيله. الإنشاء: من شاشة «الفواتير الدورية»، أو من زر «فاتورة دورية» في صفحة أي فاتورة."},{"p":"الديوان (Diwan ERP)","g":"الرئيسية","u":"index.html#لوحات-القيادة-التقارير--لوحات-القيادة-والتحليلات","h":"لوحات القيادة (التقارير ← لوحات القيادة والتحليلات)","t":"التدفق النقدي المتوقع لـ 13 أسبوعاً: يجمع الذمم حسب الاستحقاق، والفواتير الدورية، والشيكات، والموردين، والرواتب. أعمار الذمم: للعملاء والموردين، مع أكثر المتأخرين وإرسال كشف الحساب لهم. الربحية: حسب الصنف والعميل والمشروع. الموازنة: الموازنة المعتمدة مقابل الفعلي. العملة: كل المبالغ بالعملة الأساسية، ومنها أيضاً إقرار ضريبة القيمة المضافة وأعمار الذمم."},{"p":"الديوان (Diwan ERP)","g":"الرئيسية","u":"index.html#الأمان-والعزل","h":"الأمان والعزل","t":"العزل: نطاق عام يفشل مغلقاً (fail-closed) على كل جداول المنشأة، والتحقق من المعرفات المرسلة بقاعدة tenant_exists. الجلسات: لكل نطاق فرعي جلسته، ويُرفض أي مستخدم على نطاق منشأة أخرى. الصلاحيات: مصفوفة لكل منشأة (module.resource.action) مربوطة بكل مسار، والمسار غير المربوط مرفوض. رموز API لا تتجاوز صلاحيات صاحبها. الملفات: على قرص خاص وتُخدم برمز مشفر. التدقيق: سجلات تدقيق لكل منشأة، وسجل منفصل لعمليات المنصة."},{"p":"الديوان (Diwan ERP)","g":"الرئيسية","u":"index.html#البدء-السريع-تطوير","h":"البدء السريع (تطوير)","t":"composer install && npm ci && npm run build cp .env.example .env && php artisan key:generate php artisan migrate --seed # منشأة تجريبية: anas / مدير المنصة: admin@diwan.io php artisan serve # افتح http://localhost:8000/?tenant=anas"},{"p":"الديوان (Diwan ERP)","g":"الرئيسية","u":"index.html#الاختبارات","h":"الاختبارات","t":"php artisan test # SQLite في الذاكرة php artisan test -c phpunit.mysql.xml # MySQL 8 (قاعدة diwan_test) vendor/bin/pint --test"},{"p":"الديوان (Diwan ERP)","g":"الرئيسية","u":"index.html#اختبارات-المتصفح-e2e","h":"اختبارات المتصفح (E2E)","t":"اختبارات Playwright في tests/e2e/ تشغّل النظام في متصفح حقيقي وتنفّذ ما يفعله المستخدم بالنقر: فاتورة بيع ثم طباعتها مشروع بجدول كميات أمر شراء صنف بفئة ضريبية إعدادات الموارد البشرية الشعار في الطباعة مرور على كل شاشات النظام للتأكد من خلوها من الأخطاء npm run build npx playwright install chromium # مرة واحدة npm run test:e2e قاعدة البيانات: تُنشأ قاعدة SQLite مستقلة (database/e2e.sqlite) من البيانات التجريبية في كل تشغيل، ولا تُمسّ قاعدة التطوير. متصفح مثبّت مسبقاً: إن وُجد، مرّر مساره عبر PLAYWRIGHT_CHROMIUM_PATH."},{"p":"الديوان (Diwan ERP)","g":"الرئيسية","u":"index.html#التشغيل-على-ويندوز","h":"التشغيل على ويندوز","t":"الطريقة الموصى بها: تثبيت «الديوان» على ويندوز (لا تحتاج أي برنامج مسبق). النسخ القديمة المثبّتة على MAMP أو Laragon تبقى موثقة في تشغيل النظام وتحديثه على ويندوز (MAMP)."},{"p":"تثبيت «الديوان»: من أين أبدأ؟","g":"التثبيت والبدء","u":"install.html","h":"تثبيت «الديوان»: من أين أبدأ؟","t":"«الديوان» نظام مجاني لإدارة المنشآت: محاسبة، ومبيعات ومشتريات، ومخزون، ورواتب، وفوترة إلكترونية. يمكنك تثبيته بنفسك حتى لو لم تكن لديك خبرة تقنية. اختر الطريقة المناسبة لك من الجدول، ثم اتبع دليلها خطوة بخطوة."},{"p":"تثبيت «الديوان»: من أين أبدأ؟","g":"التثبيت والبدء","u":"install.html#أين-تريد-تشغيل-النظام","h":"أين تريد تشغيل النظام؟","t":"أين؟ يناسب من؟ الصعوبة الدليل جهاز ويندوز في المكتب منشأة واحدة. يعمل على هذا الجهاز، وتفتحه بقية أجهزة المكتب والجوالات المتصلة بنفس الشبكة. ⭐ سهل: ملف واحد تنقر عليه تثبيت «الديوان» على ويندوز جهاز ماك في المكتب مثل ويندوز. ⭐ سهل: سطر واحد تلصقه تثبيت «الديوان» على ماك جهاز لينكس في المكتب (Ubuntu أو Mint) مثل ويندوز. ⭐ سهل: سطر واحد تلصقه تثبيت «الديوان» على لينكس (Ubuntu / Mint / Debian) خادم على الإنترنت (مثل DigitalOcean) من يريد فتح النظام من أي مكان، أو تقديمه لعدة منشآت لكل منها رابطها. ⭐⭐ متوسط: يحتاج نطاقاً (Domain) دليل إعداد خادم «الديوان» من الصفر لست متأكداً؟ ابدأ بجهاز في المكتب. يمكنك لاحقاً نقل بياناتك إلى خادم بالنسخة الاحتياطية."},{"p":"تثبيت «الديوان»: من أين أبدأ؟","g":"التثبيت والبدء","u":"install.html#الفرق-بين-جهاز-في-المكتب-وخادم","h":"الفرق بين «جهاز في المكتب» و«خادم»","t":"جهاز في المكتب: يعمل النظام على أحد أجهزتك، وتبقى بياناتك عندك. لا تحتاج اشتراكاً ولا نطاقاً. يعمل حتى لو انقطع الإنترنت. تحتاج الإنترنت فقط لإرسال الفواتير إلى هيئة الزكاة، وللتحديثات. يجب أن يبقى هذا الجهاز مشغّلاً ما دام الموظفون يعملون. خادم: يعمل النظام على جهاز في مركز بيانات، طوال الوقت. تفتحه من البيت والجوال والفروع البعيدة. تكلفته اشتراك شهري بسيط للخادم، ويحتاج نطاقاً."},{"p":"تثبيت «الديوان»: من أين أبدأ؟","g":"التثبيت والبدء","u":"install.html#ما-يحتاجه-الجهاز","h":"ما يحتاجه الجهاز","t":"الحد الأدنى الموصى به النظام ويندوز 10 أو 11 (64-بت)، أو ماك حديث، أو Ubuntu 22.04 فأحدث — الذاكرة (RAM) 4 جيجابايت 8 جيجابايت المساحة الفارغة 3 جيجابايت 10 جيجابايت (للنسخ الاحتياطية) الإنترنت أثناء التثبيت فقط — لا تحتاج تثبيت أي برنامج قبل البدء. المثبّت ينزّل كل ما يلزم بنفسه."},{"p":"تثبيت «الديوان»: من أين أبدأ؟","g":"التثبيت والبدء","u":"install.html#ماذا-يحدث-أثناء-التثبيت","h":"ماذا يحدث أثناء التثبيت؟","t":"ينزّل المثبّت البرامج التي يعمل عليها النظام ويجهزها: PHP: اللغة التي كُتب بها النظام. قاعدة بيانات MySQL: المكان الذي تُحفظ فيه بياناتك. آخر إصدار من «الديوان». ثم يضبطها لتعمل تلقائياً كلما شُغّل الجهاز. في النهاية يفتح المتصفح على صفحة «الإعداد الأول»: تكتب فيها اسم منشأتك وبيانات حساب المدير، وتبدأ العمل. رسائل التثبيت بالإنجليزية: نافذة الأوامر في ويندوز وماك ولينكس لا تعرض العربية بشكل صحيح، لذلك تظهر رسائل التثبيت بالإنجليزية. كل دليل يشرح معنى ما يظهر لك بالعربية."},{"p":"تثبيت «الديوان»: من أين أبدأ؟","g":"التثبيت والبدء","u":"install.html#بعد-التثبيت-أمور-مهمة","h":"بعد التثبيت: أمور مهمة","t":"احفظ ملف كلمات المرور (secrets.txt) في مكان آمن خارج الجهاز، مثل فلاش أو بريدك. مكانه مذكور في دليل جهازك. النسخ الاحتياطي: يأخذ النظام نسخة احتياطية مشفّرة كل ليلة. انسخها أسبوعياً إلى فلاش أو تخزين سحابي. إن تعطل الجهاز، فهذه النسخ هي بياناتك. التحديثات: عند صدور إصدار جديد يظهر في لوحة التحكم شريط أخضر لمالك المنشأة فيه زر «حدّث الآن»؛ يعمل التحديث في الخلفية دون إيقاف النظام ثم تُعاد الصفحة تلقائياً. وإن لم تضغط الزر يتحدّث النظام تلقائياً كل ليلة الساعة 3:30 فجراً. يأخذ نسخة احتياطية قبل أي تغيير في قاعدة البيانات، ويرجع للإصدار السابق تلقائياً إن حدثت مشكلة. أجهزة المكتب: العنوان الذي تفتح به بقية الأجهزة النظام تجده دائماً في الإعدادات داخل النظام، ومعه رمز QR للجوال."},{"p":"تثبيت «الديوان»: من أين أبدأ؟","g":"التثبيت والبدء","u":"install.html#تحتاج-مساعدة","h":"تحتاج مساعدة؟","t":"صوّر الشاشة التي ظهرت فيها المشكلة، وافتح طلباً في صفحة المشروع: github.com/turkialawlqy/Diwan-ERP/issues"},{"p":"تثبيت «الديوان»: من أين أبدأ؟","g":"التثبيت والبدء","u":"install.html#لصاحب-المشروع-نشر-إصدار-جديد","h":"لصاحب المشروع: نشر إصدار جديد","t":"المثبّتات تنزّل دائماً آخر إصدار منشور في صفحة Releases. إن لم يُنشر أي إصدار، يفشل التثبيت برسالة «Could not download Diwan». لنشر إصدار: في GitHub افتح المستودع، ثم Releases ← Draft a new release. في Choose a tag اكتب رقم الإصدار، مثل v1.0.0، واختر Create new tag. في Target اختر الفرع الذي فيه النسخة المستقرة. اكتب عنواناً وملاحظات (ما الجديد)، ثم Publish release. انتظر 5-10 دقائق: يبني GitHub Actions حزمة النظام الجاهزة diwan-erp.zip ويضيفها مع المثبّتات إلى الإصدار تلقائياً. تتابع التقدم من تبويب Actions. بعد ذلك تحصل كل الأجهزة المثبّتة على الإصدار الجديد في تحديثها الليلي."},{"p":"تثبيت «الديوان»: من أين أبدأ؟","g":"التثبيت والبدء","u":"install.html#التحديث-من-الشيفرة-المصدرية-للمطوّرين-فقط-مشروع-منسوخ-بـ-git-clone","h":"التحديث من الشيفرة المصدرية (للمطوّرين فقط: مشروع منسوخ بـ git clone)","t":"لا تستعمل هذا القسم على نسخة ثبّتها المثبّت (مجلد مثل C:\\Diwan\\releases\\... أو ~/Diwan): تلك ليست نسخة git، وتتحدّث وحدها من لوحة التحكم. الواجهة المبنيّة (public/build) لا تُرفع إلى GitHub، فبعد كل git pull شغّل: git pull composer update-app يثبّت هذا الحزم ويحدّث قاعدة البيانات ويعيد بناء الواجهة. بدون إعادة البناء يبقى الشكل القديم وتظهر ميزات الدول الأخرى. من يثبّت من الحزمة الجاهزة (Release) يحصل على كل ذلك تلقائياً عند صدور إصدار جديد."},{"p":"تثبيت «الديوان» على ويندوز","g":"التثبيت والبدء","u":"install-windows.html","h":"تثبيت «الديوان» على ويندوز","t":"دليل خطوة بخطوة لتثبيت النظام على جهاز ويندوز 10 أو 11، حتى لو كان الجهاز جديداً ولا يحتوي أي برنامج. لا تحتاج أي خبرة تقنية. يستغرق التثبيت 10-20 دقيقة، معظمها تنزيل."},{"p":"تثبيت «الديوان» على ويندوز","g":"التثبيت والبدء","u":"install-windows.html#قبل-البدء","h":"قبل البدء","t":"جهاز ويندوز 10 أو 11، وفيه 3 جيجابايت فارغة على الأقل في القرص C:. اتصال بالإنترنت. حساب ويندوز بصلاحية مدير (Administrator). غالباً حسابك كذلك إن كنت أنت من أعد الجهاز. اختر الجهاز الذي سيبقى مشغّلاً طوال وقت العمل، لأن بقية أجهزة المكتب تتصل به."},{"p":"تثبيت «الديوان» على ويندوز","g":"التثبيت والبدء","u":"install-windows.html#الخطوة-1-نزّل-ملف-التثبيت","h":"الخطوة 1: نزّل ملف التثبيت","t":"افتح هذا الرابط في المتصفح: https://github.com/turkialawlqy/Diwan-ERP/releases/latest/download/Diwan-Setup.bat سيُنزَّل ملف صغير اسمه Diwan-Setup.bat إلى مجلد التنزيلات (Downloads). إن سألك المتصفح «هل تريد الاحتفاظ بهذا الملف؟» اختر احتفاظ (Keep)."},{"p":"تثبيت «الديوان» على ويندوز","g":"التثبيت والبدء","u":"install-windows.html#الخطوة-2-شغّل-الملف","h":"الخطوة 2: شغّل الملف","t":"افتح مجلد التنزيلات وانقر نقراً مزدوجاً على Diwan-Setup.bat. قد تظهر شاشة زرقاء عنوانها «Windows protected your PC» (حماية ويندوز). هذا طبيعي لأي ملف جديد غير موقّع تجارياً: اضغط على More info (مزيد من المعلومات). ثم اضغط Run anyway (تشغيل على أي حال). سيسألك ويندوز: «هل تريد السماح لهذا التطبيق بإجراء تغييرات على جهازك؟». اضغط نعم (Yes)."},{"p":"تثبيت «الديوان» على ويندوز","g":"التثبيت والبدء","u":"install-windows.html#الخطوة-3-انتظر-حتى-ينتهي","h":"الخطوة 3: انتظر حتى ينتهي","t":"تفتح نافذة سوداء وتظهر فيها خطوات التثبيت بالإنجليزية (لأن هذه النافذة لا تعرض العربية جيداً). لا تغلقها، واتركها حتى تنتهي. ما يظهر معناه [1/9] Checking this computer فحص نظام التشغيل والمساحة الفارغة. [2/9] Microsoft Visual C++ runtime برنامج صغير من مايكروسوفت يحتاجه PHP. [3/9] PHP 8.3 تنزيل PHP، اللغة التي كُتب بها النظام. [4/9] Database (MariaDB) تنزيل قاعدة البيانات وتشغيلها كخدمة. [5/9] Downloading the latest Diwan release تنزيل النظام نفسه (نحو 100 ميجابايت). [6/9] Settings and database tables تجهيز الإعدادات وجداول البيانات. [7/9] Starting Diwan automatically with Windows ضبط التشغيل التلقائي مع ويندوز. [8/9] Allowing the office devices to connect السماح لأجهزة المكتب بالوصول. [9/9]"},{"p":"تثبيت «الديوان» على ويندوز","g":"التثبيت والبدء","u":"install-windows.html#الخطوة-4-الإعداد-الأول","h":"الخطوة 4: الإعداد الأول","t":"بعد النجاح يفتح المتصفح تلقائياً على صفحة «تم تثبيت النظام بنجاح». اكتب فيها: اسم المنشأة، والدولة، والعملة. انتبه: العملة لا يمكن تغييرها بعد البدء. حساب المدير: الاسم، والبريد الإلكتروني، وكلمة المرور. البريد هو اسم الدخول، ولا يحتاج تأكيداً. اضغط «ابدأ استخدام النظام». تدخل إلى لوحة التحكم مباشرة. احفظ البريد وكلمة المرور. هذه الصفحة لا تظهر مرة أخرى."},{"p":"تثبيت «الديوان» على ويندوز","g":"التثبيت والبدء","u":"install-windows.html#فتح-النظام-بعد-ذلك","h":"فتح النظام بعد ذلك","t":"من هذا الجهاز: انقر نقراً مزدوجاً على اختصار «الديوان» على سطح المكتب، أو افتح http://localhost:8000. من أجهزة المكتب الأخرى والجوالات: في النظام افتح الإعدادات. ستجد مربع «الوصول من أجهزة المكتب»، وفيه العنوان، مثل http://192.168.1.20:8000، ورمز QR. اكتب العنوان في متصفح أي جهاز متصل بنفس الراوتر، أو امسح الرمز بكاميرا الجوال. أضف لكل موظف حساباً من الإعدادات ← المستخدمين. النظام يعمل تلقائياً مع كل تشغيل للجهاز، حتى قبل تسجيل الدخول إلى ويندوز. لا تحتاج تشغيله يدوياً."},{"p":"تثبيت «الديوان» على ويندوز","g":"التثبيت والبدء","u":"install-windows.html#الأدوات-في-قائمة-ابدأ","h":"الأدوات في قائمة ابدأ","t":"افتح قائمة ابدأ ← الديوان: الأداة متى تستخدمها فتح الديوان يفتح النظام في المتصفح. تحديث الديوان يحدّث فوراً بدلاً من انتظار التحديث الليلي. نسخة احتياطية الآن قبل أي عمل كبير، أو قبل نقل الجهاز. إعادة تشغيل الديوان إن توقف النظام عن الاستجابة، أو بعد تعديل الإعدادات. إلغاء تثبيت الديوان يزيل النظام، ويسألك هل تحتفظ ببياناتك. كل أداة تطلب صلاحية المدير: اضغط نعم."},{"p":"تثبيت «الديوان» على ويندوز","g":"التثبيت والبدء","u":"install-windows.html#أماكن-الملفات","h":"أماكن الملفات","t":"المجلد أو الملف المحتوى C:\\Diwan\\secrets.txt كلمات المرور. انسخه إلى فلاش أو بريدك واحتفظ به. C:\\Diwan\\shared\\storage\\app\\backups\\ النسخ الاحتياطية الليلية. انسخها أسبوعياً إلى فلاش أو تخزين سحابي. C:\\Diwan\\shared\\.env الإعدادات، مثل البريد. C:\\Diwan\\data\\ قاعدة البيانات (لا تعدّل فيها يدوياً). C:\\Diwan\\logs\\ سجلات التشغيل والتحديث."},{"p":"تثبيت «الديوان» على ويندوز","g":"التثبيت والبدء","u":"install-windows.html#إرسال-الفواتير-بالبريد-اختياري","h":"إرسال الفواتير بالبريد (اختياري)","t":"لإرسال الفواتير وكشوف الحساب إلى العملاء بالبريد: افتح الملف C:\\Diwan\\shared\\.env بالمفكرة (Notepad): زر يمين ← فتح باستخدام ← Notepad. عدّل هذه الأسطر ببيانات بريدك (من مزود البريد، مثل Zoho أو Gmail): MAIL_MAILER=smtp MAIL_HOST=smtp.zoho.com MAIL_PORT=587 MAIL_USERNAME=invoices@your-company.com MAIL_PASSWORD=كلمة-مرور-البريد MAIL_FROM_ADDRESS=invoices@your-company.com احفظ الملف، ثم شغّل قائمة ابدأ ← الديوان ← إعادة تشغيل الديوان."},{"p":"تثبيت «الديوان» على ويندوز","g":"التثبيت والبدء","u":"install-windows.html#النقل-إلى-جهاز-جديد","h":"النقل إلى جهاز جديد","t":"على الجهاز القديم: نسخة احتياطية الآن، ثم انسخ إلى فلاش: مجلد C:\\Diwan\\shared\\storage\\app\\backups\\؛ الملف C:\\Diwan\\secrets.txt. على الجهاز الجديد: ثبّت النظام بهذا الدليل. لا تكمل صفحة الإعداد الأول. انسخ ملف النسخة الاحتياطية إلى C:\\Diwan\\shared\\storage\\app\\backups\\. افتح PowerShell كمدير (زر يمين على ابدأ ← Terminal (Admin)) واكتب: cd C:\\Diwan\\current C:\\Diwan\\bin\\php\\php.exe artisan erp:restore اسم-ملف-النسخة.zip تحتاج كلمة BACKUP_PASSWORD القديمة من secrets.txt القديم. ضعها في C:\\Diwan\\shared\\.env قبل الأمر، ثم شغّل «إعادة تشغيل الديوان»."},{"p":"تثبيت «الديوان» على ويندوز","g":"التثبيت والبدء","u":"install-windows.html#حل-المشكلات","h":"حل المشكلات","t":"المشكلة الحل أغلقت النافذة السوداء فوراً، أو لم يحدث شيء تأكد أنك ضغطت نعم في سؤال الصلاحيات. شغّل الملف مرة أخرى. Could not download ... تحقق من الإنترنت، ثم أعد تشغيل Diwan-Setup.bat. إعادة التشغيل آمنة وتكمل من حيث توقفت. PHP extension missing أو Could not install Visual C++ أعد تشغيل الجهاز، ثم شغّل Diwan-Setup.bat مرة أخرى. برنامج مكافحة الفيروسات حذف ملفاً أو منعه أضف المجلد C:\\Diwan إلى الاستثناءات في برنامج الحماية، ثم أعد التثبيت. Diwan did not answer on port 8000 شغّل «إعادة تشغيل الديوان». إن استمرت المشكلة، أرسل الملف C:\\Diwan\\logs\\web.log لطلب المساعدة. أجهزة المكتب لا تفتح العنوان 1. تأكد أن الجهاز الآخر على نفس الراوتر. 2. اجعل الشبكة خاصة: الإعدادات ← الشبكة والإنترنت ← Wi-Fi"},{"p":"تثبيت «الديوان» على ماك","g":"التثبيت والبدء","u":"install-mac.html","h":"تثبيت «الديوان» على ماك","t":"دليل خطوة بخطوة لتثبيت النظام على جهاز ماك، حتى لو لم يكن عليه أي برنامج مسبق. لا تحتاج خبرة تقنية. يستغرق 10-20 دقيقة في أول مرة."},{"p":"تثبيت «الديوان» على ماك","g":"التثبيت والبدء","u":"install-mac.html#قبل-البدء","h":"قبل البدء","t":"جهاز ماك بنظام macOS 13 (Ventura) أو أحدث، وفيه 5 جيجابايت فارغة. اتصال بالإنترنت. كلمة مرور الماك: التي تدخل بها إلى الجهاز. اختر الجهاز الذي سيبقى مشغّلاً ومسجّلاً الدخول طوال وقت العمل."},{"p":"تثبيت «الديوان» على ماك","g":"التثبيت والبدء","u":"install-mac.html#الخطوة-1-افتح-terminal","h":"الخطوة 1: افتح «Terminal»","t":"Terminal برنامج موجود في كل ماك لكتابة الأوامر: اضغط ⌘ + مسافة (Command + Space). اكتب Terminal واضغط Enter."},{"p":"تثبيت «الديوان» على ماك","g":"التثبيت والبدء","u":"install-mac.html#الخطوة-2-الصق-أمر-التثبيت","h":"الخطوة 2: الصق أمر التثبيت","t":"انسخ هذا السطر كاملاً، والصقه في Terminal بـ ⌘ + V، ثم اضغط Enter: /bin/bash -c \"$(curl -fsSL https://github.com/turkialawlqy/Diwan-ERP/releases/latest/download/install-mac.sh)\""},{"p":"تثبيت «الديوان» على ماك","g":"التثبيت والبدء","u":"install-mac.html#الخطوة-3-أجب-عن-طلبين-فقط","h":"الخطوة 3: أجب عن طلبين فقط","t":"الرسائل تظهر بالإنجليزية، لأن Terminal لا يعرض العربية جيداً. Password: اكتب كلمة مرور الماك واضغط Enter. لن تظهر أي حروف أثناء الكتابة، وهذا طبيعي. اكتبها واضغط Enter. يُطلب هذا مرة واحدة لتثبيت Homebrew، وهو أداة التثبيت المعتمدة للماك. Press RETURN/ENTER to continue: اضغط Enter. قد تظهر نافذة لتثبيت «أدوات المطوّر» (Command Line Tools). اضغط Install (تثبيت)، وانتظر حتى تنتهي. بعدها تعمل الخطوات وحدها: ما يظهر معناه 1/6 Homebrew أداة تثبيت البرامج. 2/6 Installing PHP and the MySQL database PHP وقاعدة البيانات. 3/6 Downloading the latest Diwan release تنزيل النظام. 4/6 Database and settings تجهيز البيانات والإعدادات. 5/6 Starting Diwan automatically when you log in التشغيل التلقائي. 6/6 Des"},{"p":"تثبيت «الديوان» على ماك","g":"التثبيت والبدء","u":"install-mac.html#الخطوة-4-الإعداد-الأول","h":"الخطوة 4: الإعداد الأول","t":"يفتح المتصفح تلقائياً على صفحة «تم تثبيت النظام بنجاح»: اكتب اسم المنشأة، والدولة، والعملة. انتبه: العملة لا تتغير بعد البدء. اكتب حساب المدير: الاسم، والبريد (اسم الدخول)، وكلمة المرور. اضغط «ابدأ استخدام النظام». قد يسألك الماك: «Do you want the application php to accept incoming network connections?» اضغط Allow (سماح)، لتتمكن أجهزة المكتب من الاتصال."},{"p":"تثبيت «الديوان» على ماك","g":"التثبيت والبدء","u":"install-mac.html#فتح-النظام-بعد-ذلك","h":"فتح النظام بعد ذلك","t":"من هذا الماك: انقر على اختصار «الديوان» على سطح المكتب، أو افتح http://localhost:8000. من أجهزة المكتب والجوالات: العنوان ورمز QR في الإعدادات داخل النظام، في مربع «الوصول من أجهزة المكتب». يعمل من أي جهاز متصل بنفس الراوتر. التشغيل التلقائي: يعمل النظام كلما سجّلت الدخول إلى الماك. لا تسجّل الخروج من حسابك في الماك أثناء العمل. قفل الشاشة لا يوقفه. منع النوم: امنع الماك من النوم أثناء العمل. من إعدادات النظام ← البطارية (أو موفر الطاقة في أجهزة المكتب)، فعّل «منع دخول الكمبيوتر في وضع السكون تلقائياً عند إيقاف تشغيل الشاشة». انطفاء الشاشة وحده لا يضر."},{"p":"تثبيت «الديوان» على ماك","g":"التثبيت والبدء","u":"install-mac.html#أماكن-الملفات","h":"أماكن الملفات","t":"المجلد أو الملف المحتوى ~/Diwan/secrets.txt كلمات المرور. انسخه إلى مكان آمن. ~/Diwan/shared/storage/app/backups/ النسخ الاحتياطية الليلية. انسخها أسبوعياً إلى فلاش أو iCloud. ~/Diwan/shared/.env الإعدادات، مثل البريد. ~ يعني مجلدك الشخصي. لفتحه من Finder اضغط ⌘ + Shift + H."},{"p":"تثبيت «الديوان» على ماك","g":"التثبيت والبدء","u":"install-mac.html#أوامر-مفيدة-في-terminal","h":"أوامر مفيدة (في Terminal)","t":"المطلوب الأمر تحديث الآن bash ~/Diwan/current/deploy/mac/update.sh نسخة احتياطية الآن cd ~/Diwan/current && $(brew --prefix php@8.3)/bin/php artisan erp:backup إعادة تشغيل النظام launchctl kickstart -k gui/$(id -u)/com.diwan.web إرسال الفواتير بالبريد: عدّل أسطر MAIL_ في ~/Diwan/shared/.env (بـ TextEdit). الأسطر مشروحة في دليل ويندوز. ثم نفّذ: cd ~/Diwan/current && $(brew --prefix php@8.3)/bin/php artisan optimize && launchctl kickstart -k gui/$(id -u)/com.diwan.web"},{"p":"تثبيت «الديوان» على ماك","g":"التثبيت والبدء","u":"install-mac.html#حل-المشكلات","h":"حل المشكلات","t":"المشكلة الحل command not found: brew بعد تثبيته أغلق Terminal وافتحه من جديد، ثم الصق أمر التثبيت مرة أخرى. إعادة التشغيل آمنة. Could not download Diwan تحقق من الإنترنت، وأعد لصق الأمر. The database did not start أعد تشغيل الماك، ثم الصق أمر التثبيت مرة أخرى. أجهزة المكتب لا تفتح العنوان تأكد أنك اخترت Allow لاتصالات php. أو: إعدادات النظام ← الشبكة ← جدار الحماية ← خيارات، وأضف php واسمح له. النظام لا يفتح نفّذ أمر «إعادة تشغيل النظام» من الجدول أعلاه. لأي مشكلة أخرى: صوّر Terminal وافتح طلباً في صفحة المشروع."},{"p":"تثبيت «الديوان» على لينكس (Ubuntu / Mint / Debian)","g":"التثبيت والبدء","u":"install-linux.html","h":"تثبيت «الديوان» على لينكس (Ubuntu / Mint / Debian)","t":"دليل خطوة بخطوة لتثبيت النظام على جهاز لينكس مكتبي للاستخدام في المكتب. لا تحتاج خبرة تقنية. يستغرق 5-15 دقيقة. لخادم على الإنترنت (مثل DigitalOcean)، مع نطاق وشهادة SSL لعدة منشآت، استخدم دليل إعداد خادم «الديوان» من الصفر بدلاً من هذا الدليل."},{"p":"تثبيت «الديوان» على لينكس (Ubuntu / Mint / Debian)","g":"التثبيت والبدء","u":"install-linux.html#قبل-البدء","h":"قبل البدء","t":"النظام: Ubuntu 22.04 أو أحدث، أو Linux Mint 21 أو أحدث، أو Debian 12. المساحة: 3 جيجابايت فارغة على الأقل. الإنترنت: اتصال أثناء التثبيت. كلمة مرور حسابك: التي تدخل بها إلى الجهاز، ويجب أن يملك حسابك صلاحية sudo. الحساب الأول على الجهاز يملكها عادة."},{"p":"تثبيت «الديوان» على لينكس (Ubuntu / Mint / Debian)","g":"التثبيت والبدء","u":"install-linux.html#الخطوة-1-افتح-الطرفية-terminal","h":"الخطوة 1: افتح الطرفية (Terminal)","t":"اضغط Ctrl + Alt + T، أو ابحث عن Terminal في قائمة البرامج."},{"p":"تثبيت «الديوان» على لينكس (Ubuntu / Mint / Debian)","g":"التثبيت والبدء","u":"install-linux.html#الخطوة-2-الصق-أمر-التثبيت","h":"الخطوة 2: الصق أمر التثبيت","t":"انسخ السطر كاملاً، والصقه في الطرفية بـ Ctrl + Shift + V، ثم اضغط Enter: sudo bash -c \"$(curl -fsSL https://github.com/turkialawlqy/Diwan-ERP/releases/latest/download/install-linux.sh)\" إن ظهر curl: command not found: نفّذ أولاً sudo apt install -y curl، ثم الصق الأمر مرة أخرى. عند [sudo] password: اكتب كلمة مرور حسابك، واضغط Enter. لن تظهر الحروف أثناء الكتابة، وهذا طبيعي."},{"p":"تثبيت «الديوان» على لينكس (Ubuntu / Mint / Debian)","g":"التثبيت والبدء","u":"install-linux.html#الخطوة-3-انتظر-حتى-ينتهي","h":"الخطوة 3: انتظر حتى ينتهي","t":"الرسائل تظهر بالإنجليزية، لأن الطرفية لا تعرض العربية جيداً: ما يظهر معناه 1/6 Installing PHP and the database تثبيت PHP وقاعدة البيانات MySQL. 2/6 Downloading the latest Diwan release تنزيل النظام. 3/6 Database and settings تجهيز البيانات والإعدادات. 4/6 Starting Diwan automatically with the computer التشغيل التلقائي مع الجهاز. 5/6 Allowing the office devices to connect السماح لأجهزة المكتب بالوصول. 6/6 Applications menu shortcut اختصار في قائمة البرامج. Installed successfully! تم التثبيت بنجاح."},{"p":"تثبيت «الديوان» على لينكس (Ubuntu / Mint / Debian)","g":"التثبيت والبدء","u":"install-linux.html#الخطوة-4-الإعداد-الأول","h":"الخطوة 4: الإعداد الأول","t":"افتح المتصفح على http://localhost:8000، أو ابحث عن الديوان في قائمة البرامج. ستظهر صفحة «تم تثبيت النظام بنجاح»: اكتب اسم المنشأة، والدولة، والعملة. العملة لا تتغير بعد البدء. اكتب حساب المدير: الاسم، والبريد (اسم الدخول)، وكلمة المرور. اضغط «ابدأ استخدام النظام»."},{"p":"تثبيت «الديوان» على لينكس (Ubuntu / Mint / Debian)","g":"التثبيت والبدء","u":"install-linux.html#الاستخدام-اليومي","h":"الاستخدام اليومي","t":"تشغيل النظام: يعمل تلقائياً مع تشغيل الجهاز، حتى قبل تسجيل الدخول. أجهزة المكتب والجوالات: العنوان ورمز QR في الإعدادات داخل النظام، في مربع «الوصول من أجهزة المكتب». التحديث: يتحدّث تلقائياً كل ليلة الساعة 3:30. يأخذ نسخة احتياطية قبل تغيير قاعدة البيانات، ويرجع للإصدار السابق تلقائياً إن حدثت مشكلة. المطلوب الأمر تحديث الآن sudo bash /opt/diwan/current/deploy/linux/update.sh نسخة احتياطية الآن cd /opt/diwan/current && sudo -u diwan php artisan erp:backup إعادة تشغيل النظام sudo systemctl restart diwan-web diwan-queue diwan-scheduler حالة النظام systemctl status diwan-web"},{"p":"تثبيت «الديوان» على لينكس (Ubuntu / Mint / Debian)","g":"التثبيت والبدء","u":"install-linux.html#أماكن-الملفات","h":"أماكن الملفات","t":"المجلد أو الملف المحتوى /opt/diwan/secrets.txt كلمات المرور. انسخه إلى مكان آمن (sudo cat /opt/diwan/secrets.txt). /opt/diwan/shared/storage/app/backups/ النسخ الاحتياطية الليلية. انسخها أسبوعياً إلى فلاش أو تخزين سحابي. /opt/diwan/shared/.env الإعدادات، مثل البريد. للتعديل: sudo nano /opt/diwan/shared/.env، ثم «إعادة تشغيل النظام» من الجدول أعلاه. لإعداد البريد، انظر أسطر MAIL_ في دليل ويندوز. بعد تعديلها نفّذ: cd /opt/diwan/current && sudo -u diwan php artisan optimize && sudo systemctl restart diwan-web diwan-queue diwan-scheduler"},{"p":"تثبيت «الديوان» على لينكس (Ubuntu / Mint / Debian)","g":"التثبيت والبدء","u":"install-linux.html#حل-المشكلات","h":"حل المشكلات","t":"المشكلة الحل This installer is for Ubuntu, Debian and Mint نظامك يستخدم مدير حزم آخر. استخدم دليل الخادم كمرجع للحزم المطلوبة. Could not download Diwan تحقق من الإنترنت، ثم أعد لصق الأمر. إعادة التشغيل آمنة. أجهزة المكتب لا تفتح العنوان تأكد أنها على نفس الراوتر. إن كان لديك جدار حماية غير ufw، اسمح بالمنفذ 8000. النظام لا يفتح sudo systemctl restart diwan-web، ثم راجع: journalctl -u diwan-web -n 50. لأي مشكلة أخرى: صوّر الطرفية وافتح طلباً في صفحة المشروع."},{"p":"تشغيل النظام وتحديثه على ويندوز (MAMP)","g":"التثبيت والبدء","u":"windows-local.html","h":"تشغيل النظام وتحديثه على ويندوز (MAMP)","t":"لتثبيت جديد استخدم تثبيت «الديوان» على ويندوز: ملف واحد ينزّل كل شيء، ولا يحتاج MAMP ولا Git ولا Node. هذا الدليل للنسخ القديمة المثبّتة على MAMP أو Laragon فقط. هذا الدليل لنسخة تعمل على جهاز ويندوز، مثل C:\\MAMP\\htdocs\\diwan. سكربت التحديث يسحب آخر نسخة من GitHub ويجهّزها كاملة، ويعمل بالنقر أو تلقائياً كل ساعة."},{"p":"تشغيل النظام وتحديثه على ويندوز (MAMP)","g":"التثبيت والبدء","u":"windows-local.html#المتطلبات-مرة-واحدة","h":"المتطلبات (مرة واحدة)","t":"الأداة ملاحظة Git for Windows يتضمن Git Credential Manager لتسجيل الدخول إلى GitHub Node.js LTS لبناء الواجهة MAMP بـ PHP 8.2 أو أحدث يكتشف السكربت PHP من C:\\MAMP\\bin\\php تلقائياً لا حاجة لتثبيت Composer، فالسكربت ينزّله إن لم يجده."},{"p":"تشغيل النظام وتحديثه على ويندوز (MAMP)","g":"التثبيت والبدء","u":"windows-local.html#أول-تحديث","h":"أول تحديث","t":"ضع مجلد deploy\\windows داخل C:\\MAMP\\htdocs\\diwan إن لم يكن موجوداً. انقر نقراً مزدوجاً على deploy\\windows\\update.bat. سيطلب ويندوز تسجيل الدخول إلى GitHub مرة واحدة، لأن المستودع خاص."},{"p":"تشغيل النظام وتحديثه على ويندوز (MAMP)","g":"التثبيت والبدء","u":"windows-local.html#ما-يفعله-السكربت","h":"ما يفعله السكربت","t":"إن لم يكن المجلد مرتبطاً بـ Git: يأخذ نسخة احتياطية كاملة إلى C:\\MAMP\\htdocs\\diwan-backup-التاريخ. ثم يربطه بالمستودع. يبقى كما هو: ملف .env والملفات المرفوعة في storage. يضع النظام في وضع الصيانة، ثم يأخذ نسخة احتياطية لقاعدة البيانات (diwan-preupdate-…). إن فشل النسخ يتوقف التحديث ويعود النظام كما كان. للتجاوز: -Force. ينفّذ بالترتيب: composer install --no-dev. بناء الواجهة. ترحيلات قاعدة البيانات. مزامنة الصلاحيات. تجهيز الكاش. إن نجح: يعيد النظام للعمل. إن فشل بعد تغيير الكود (ترحيل أو بناء): يبقى في وضع الصيانة حمايةً للبيانات. يطبع أمر الرجوع للإصدار السابق وأمر استعادة النسخة. أو أصلح السبب وأعد تشغيل update.bat ليُكمل. يضيف إلى .env مسار mysqldump الخاص بـ MAMP إن لم يكن موجوداً، ويع"},{"p":"تشغيل النظام وتحديثه على ويندوز (MAMP)","g":"التثبيت والبدء","u":"windows-local.html#التحديث-التلقائي","h":"التحديث التلقائي","t":"انقر مرتين على deploy\\windows\\install-auto-update.bat: التكرار: يُنشئ مهمة مجدولة باسم Diwan Auto Update، تفحص GitHub كل ساعة أثناء تسجيل دخولك إلى ويندوز. إن وُجد تحديث: تطبّقه خلال دقيقة أو اثنتين. إن لم يوجد: لا تغيّر شيئاً. إن عدّلت ملفات الكود يدوياً: لا يحدّث تلقائياً، حتى لا يضيع تعديلك. شغّل update.bat يدوياً، فيحفظ تعديلاتك جانباً بـ git stash قبل التحديث. ويسجّل أيضاً مهمتين ضروريتين تعملان كل دقيقة: Diwan Scheduler: المُجدول. يتولى النسخ الاحتياطي الليلي، وإبلاغ الهيئة بالفواتير المتأخرة، والقيود الدورية، والإهلاك، والمخصصات، والتنبيهات. Diwan Queue: الطوابير. تتولى إرسال الفواتير لهيئة الزكاة، والبريد، والـ Webhooks، وتصدير البيانات. بدونهما لا يعمل أي من ذلك. التشغيل كمسؤول: شغّ"},{"p":"تشغيل النظام وتحديثه على ويندوز (MAMP)","g":"التثبيت والبدء","u":"windows-local.html#خيارات-متقدمة","h":"خيارات متقدمة","t":"# فرع آخر (مثلاً بعد دمج التطوير في main) powershell -ExecutionPolicy Bypass -File deploy\\windows\\update.ps1 -Branch main # إعادة التجهيز دون تحديث جديد (مثلاً بعد مشكلة في البناء) powershell -ExecutionPolicy Bypass -File deploy\\windows\\update.ps1 -Force إن حُذف الفرع الحالي بعد دمجه: ينتقل السكربت تلقائياً إلى main."},{"p":"تشغيل النظام وتحديثه على ويندوز (MAMP)","g":"التثبيت والبدء","u":"windows-local.html#الاستعادة-من-نسخة-احتياطية","h":"الاستعادة من نسخة احتياطية","t":"ملفات النظام: مجلد C:\\MAMP\\htdocs\\diwan-backup-... نسخة كاملة كما كانت قبل الربط. يمكن إعادة تسميته ليحل محل المجلد الحالي. قاعدة البيانات والملفات المرفوعة: النسخ في storage\\app\\backups. للاستعادة: C:\\MAMP\\bin\\php\\php8.x\\php.exe artisan erp:restore diwan-preupdate-YYYY-MM-DD-HHMMSS.zip يحتاج الأمر BACKUP_PASSWORD نفسه الذي أُنشئت به النسخة، ويضع النظام في الصيانة أثناء الاستعادة."},{"p":"تشغيل النظام وتحديثه على ويندوز (MAMP)","g":"التثبيت والبدء","u":"windows-local.html#ملاحظة-عن-mamp","h":"ملاحظة عن MAMP","t":"يكتب السكربت مسار mysqldump الخاص بـ MAMP في .env تلقائياً. إن كان APP_ENV=production فالنسخ ترفض العمل بدون كلمة مرور، فأضف إلى .env: BACKUP_PASSWORD=كلمة-مرور-قوية"},{"p":"دليل إعداد خادم «الديوان» من الصفر","g":"الخوادم والتشغيل","u":"server-setup.html","h":"دليل إعداد خادم «الديوان» من الصفر","t":"دليل كامل لتجهيز خادم إنتاجي جديد على DigitalOcean: من إنشاء الخادم حتى تسجيل أول منشأة. كل خطوة فيها ما تضغط عليه أو تكتبه بالضبط. قبل البدء: اقرأ الدليل مرة كاملة. احجز ساعة تقريباً، معظمها انتظار لانتشار الـ DNS وتثبيت الحزم. هل تحتاج خادماً أصلاً؟ إن كان النظام لمنشأتك وحدها في مكتب واحد، فالأسهل تثبيته على جهاز في المكتب بنقرة واحدة: تثبيت «الديوان»: من أين أبدأ؟. الخادم مناسب لمن يريد الوصول من أي مكان، أو تقديم النظام لعدة منشآت. رسائل التثبيت بالإنجليزية: شاشة الأوامر (Terminal) لا تعرض العربية بشكل صحيح، لذلك تظهر رسائل السكربت بالإنجليزية. هذا الدليل يشرح كل خطوة بالعربية."},{"p":"دليل إعداد خادم «الديوان» من الصفر","g":"الخوادم والتشغيل","u":"server-setup.html#1-ما-تحتاجه-قبل-البدء","h":"1. ما تحتاجه قبل البدء","t":"العنصر ملاحظة حساب DigitalOcean بوسيلة دفع مفعّلة. نطاق (Domain) مسجّل ومفعّل مثل vatrix.app. يجب أن تكون حالته Active عند المسجّل، وأن تكون قد أكدت رسالة التحقق التي يرسلها المسجّل إلى بريدك بعد الشراء. بريد لإرسال رسائل النظام خدمة SMTP (انظر القسم 5). جهازك ويندوز بـ PowerShell، أو أي جهاز فيه ssh. مدير كلمات مرور لحفظ الأسرار التي يولّدها التثبيت."},{"p":"دليل إعداد خادم «الديوان» من الصفر","g":"الخوادم والتشغيل","u":"server-setup.html#2-إنشاء-الخادم-droplet","h":"2. إنشاء الخادم (Droplet)","t":"من لوحة DigitalOcean: Create ← Droplets. الإعداد الاختيار الموصى به السبب المنطقة (Region) Frankfurt (FRA1) أو Singapore (SGP1)، أيهما أقرب لعملائك الأقرب للسعودية والخليج. النظام (Image) Ubuntu 24.04 (LTS) x64 يأتي بـ PHP 8.3 المختبر مع النظام. Ubuntu 26.04 يأتي بـ PHP 8.5، والسكربت يعمل عليه، لكن 24.04 أكثر استقراراً للإنتاج. الحجم (Size) Basic ← Regular ← 2 GB RAM / 1 CPU / 50 GB كحد أدنى، و4 GB / 2 CPU إن كان العملاء كثيرين خادم 512MB يكفي للتجربة فقط: بناء الواجهة عليه يأخذ نحو 8 دقائق، ويضغط الذاكرة. التوثيق (Authentication) SSH Key أكثر أماناً من كلمة المرور (الخطوات أدناه). النسخ الاحتياطي (Backups) فعّل Weekly backups نسخة كاملة للخادم من DigitalOcean، إضافة إلى نسخ النظام اليومية. "},{"p":"دليل إعداد خادم «الديوان» من الصفر","g":"الخوادم والتشغيل","u":"server-setup.html#إنشاء-مفتاح-ssh-على-ويندوز-إن-لم-يكن-لديك","h":"إنشاء مفتاح SSH على ويندوز (إن لم يكن لديك)","t":"افتح PowerShell: ssh-keygen -t ed25519 -C \"your-email@example.com\" اضغط Enter لكل الأسئلة، أو ضع كلمة مرور للمفتاح إن أردت. ثم اعرض المفتاح العام وانسخه: type $env:USERPROFILE\\.ssh\\id_ed25519.pub في صفحة إنشاء الخادم: SSH Key ← New SSH Key، والصق المفتاح. اضغط Create Droplet. بعد دقيقة يظهر عنوان IP للخادم (ipv4)، سجّله، وسنسميه في هذا الدليل IP-الخادم. انتبه: استخدم عنوان IP خادمك من صفحة الـ Droplet، وليس أي عنوان من مواقع أخرى أو أمثلة."},{"p":"دليل إعداد خادم «الديوان» من الصفر","g":"الخوادم والتشغيل","u":"server-setup.html#3-ربط-النطاق-بـ-digitalocean","h":"3. ربط النطاق بـ DigitalOcean","t":"نجعل DigitalOcean يدير الـ DNS لنطاقك. هذا لازم لإصدار شهادة SSL تشمل كل النطاقات الفرعية للمنشآت (*.نطاقك) وتجديدها تلقائياً."},{"p":"دليل إعداد خادم «الديوان» من الصفر","g":"الخوادم والتشغيل","u":"server-setup.html#أ-أضف-النطاق-في-digitalocean","h":"أ. أضف النطاق في DigitalOcean","t":"Networking ← Domains ← Add Domain: اكتب نطاقك (مثل vatrix.app)، واختر الخادم، ثم Add Domain."},{"p":"دليل إعداد خادم «الديوان» من الصفر","g":"الخوادم والتشغيل","u":"server-setup.html#ب-أضف-سجلّي-a","h":"ب. أضف سجلّي A","t":"في صفحة النطاق داخل DigitalOcean أضف: Type Hostname Will direct to TTL A @ خادمك (IP-الخادم) 3600 A * خادمك (IP-الخادم) 3600 السجل الأول للنطاق الرئيسي، والثاني (*) لكل منشأة على اسمها.نطاقك."},{"p":"دليل إعداد خادم «الديوان» من الصفر","g":"الخوادم والتشغيل","u":"server-setup.html#ج-غيّر-خوادم-الأسماء-عند-مسجّل-النطاق","h":"ج. غيّر خوادم الأسماء عند مسجّل النطاق","t":"في لوحة المسجّل (GoDaddy أو Namecheap أو غيرهما) ابحث عن Nameservers ← Custom، وضع: ns1.digitalocean.com ns2.digitalocean.com ns3.digitalocean.com ثم احفظ."},{"p":"دليل إعداد خادم «الديوان» من الصفر","g":"الخوادم والتشغيل","u":"server-setup.html#د-تحقق-من-الانتشار","h":"د. تحقق من الانتشار","t":"قد يأخذ من دقائق إلى 48 ساعة، وغالباً أقل من ساعتين. من PowerShell على جهازك: nslookup -type=NS vatrix.app nslookup vatrix.app nslookup test.vatrix.app النتيجة الصحيحة: الأمر الأول يُظهر ns1.digitalocean.com وأخواته. الأمران الآخران يُظهران IP-الخادم. إن ظهر Non-existent domain بعد ساعات، فالمشكلة عند المسجّل: النطاق غير مفعّل، أو خوادم الأسماء لم تُحفظ. راجعه قبل المتابعة. يمكنك متابعة الخطوات 4 إلى 7 أثناء الانتظار، وإن لم ينتشر الـ DNS بعد فاتبع التثبيت بنطاق تجربة."},{"p":"دليل إعداد خادم «الديوان» من الصفر","g":"الخوادم والتشغيل","u":"server-setup.html#4-إنشاء-رمز-api-لشهادة-ssl","h":"4. إنشاء رمز API لشهادة SSL","t":"API ← Tokens ← Generate New Token: الحقل القيمة Name diwan-certbot Expiration No expiry؛ وإلا توقف تجديد الشهادة عند انتهاء الرمز. Scopes Custom Scopes ثم اختر domain بصلاحيتي read و update، أو Full Access إن لم تتوفر الصلاحيات المخصصة. انسخ الرمز فوراً، فهو لا يُعرض مرة أخرى، واحفظه في مدير كلمات المرور."},{"p":"دليل إعداد خادم «الديوان» من الصفر","g":"الخوادم والتشغيل","u":"server-setup.html#5-تجهيز-البريد-smtp","h":"5. تجهيز البريد (SMTP)","t":"النظام يرسل بريداً لـ: تأكيد البريد، واستعادة كلمة المرور، وإرسال الفواتير وكشوف الحساب للعملاء، وتنبيهات النسخ الاحتياطي. بدون SMTP لن تصل هذه الرسائل. الخيارات: الخدمة ملاحظة Zoho Mail أو Google Workspace إن كان لديك بريد رسمي على نطاقك. Brevo أو Mailgun أو Amazon SES خدمات إرسال مخصصة، أفضل للكميات وأقل عرضة لتصنيف الرسائل كبريد مزعج. ستحتاج: الخادم (host)، والمنفذ (port، غالباً 587)، واسم المستخدم، وكلمة المرور، وعنوان المرسل (مثل no-reply@vatrix.app). أضف سجلات SPF و DKIM التي تعطيك إياها خدمة البريد في صفحة النطاق في DigitalOcean، حتى لا تذهب الرسائل إلى البريد المزعج. يمكنك تخطي هذه الخطوة الآن وإضافة البريد لاحقاً (القسم 8)."},{"p":"دليل إعداد خادم «الديوان» من الصفر","g":"الخوادم والتشغيل","u":"server-setup.html#6-الدخول-إلى-الخادم","h":"6. الدخول إلى الخادم","t":"من جهازك افتح PowerShell (في ويندوز) أو Terminal (في ماك)، واكتب: ssh root@IP-الخادم عند أول دخول اكتب yes لقبول بصمة الخادم."},{"p":"دليل إعداد خادم «الديوان» من الصفر","g":"الخوادم والتشغيل","u":"server-setup.html#7-تشغيل-التثبيت","h":"7. تشغيل التثبيت","t":"الصق هذا السطر في الخادم واضغط Enter. ينزّل سكربت التثبيت من آخر إصدار ويشغّله: sudo bash -c \"$(curl -fsSL https://github.com/turkialawlqy/Diwan-ERP/releases/latest/download/install-server.sh)\""},{"p":"دليل إعداد خادم «الديوان» من الصفر","g":"الخوادم والتشغيل","u":"server-setup.html#الأسئلة-وإجاباتها","h":"الأسئلة وإجاباتها","t":"الأسئلة تظهر بالإنجليزية. هذا معنى كل سؤال وما تكتبه: السؤال ماذا تكتب Main domain (النطاق الرئيسي) vatrix.app، بلا https:// وبلا www. Platform administrator email (بريد مدير المنصة) بريدك؛ هو حساب إدارة المنصة كلها. Code repository (مستودع الكود) اضغط Enter لقبول المستودع العام. Branch (الفرع) اضغط Enter لقبول الفرع الافتراضي للمستودع. DO API token الرمز من القسم 4. لا يظهر أثناء الكتابة، وهذا طبيعي. SMTP host وما بعده بيانات القسم 5، أو اضغط Enter لتخطيها الآن. نسخة خاصة من المستودع (Fork خاص): إن كتبت رابطاً يبدأ بـ git@github.com: يعرض السكربت مفتاحاً يبدأ بـ ssh-ed25519. أضفه في GitHub: المستودع ← Settings ← Deploy keys ← Add deploy key، واترك «Allow write access» غير مفعّل، ثم ارجع واض"},{"p":"دليل إعداد خادم «الديوان» من الصفر","g":"الخوادم والتشغيل","u":"server-setup.html#ما-يفعله-السكربت-بعدها-تلقائياً","h":"ما يفعله السكربت بعدها (تلقائياً)","t":"الخطوة المحتوى 1 تحديث النظام، وذاكرة swap، والمنطقة الزمنية (الرياض)، والجدار الناري (المنافذ 22 و80 و443 فقط). 2 تثبيت Nginx وPHP وMySQL وRedis وSupervisor وCertbot. 3 إنشاء قاعدة البيانات ومستخدمها بكلمة مرور عشوائية. 4 التحقق من الوصول إلى المستودع. 5 سحب الكود، وتثبيت المكتبات، وبناء الواجهة. هذه أطول خطوة: دقيقتان إلى عشر دقائق حسب حجم الخادم. 6 ملف الإعدادات .env وأسراره. 7 جداول قاعدة البيانات وباقات الاشتراك. 8 إعداد Nginx. 9 شهادة SSL للنطاق وكل نطاقاته الفرعية (تتجدد تلقائياً). 10 العمليات الخلفية: الإرسال لهيئة الزكاة، والنسخ الاحتياطي اليومي، والتنبيهات، والقيود الدورية. 11 إنشاء مدير المنصة: يطلب كلمة مرور (10 أحرف على الأقل، ولا تظهر أثناء الكتابة)، ثم الفحص النهائي. تنتهي الع"},{"p":"دليل إعداد خادم «الديوان» من الصفر","g":"الخوادم والتشغيل","u":"server-setup.html#التثبيت-قبل-انتشار-الـ-dns","h":"التثبيت قبل انتشار الـ DNS","t":"إن لم ينتشر نطاقك بعد، يمكنك التثبيت والتجربة الآن بنطاق تجربة مجاني يعمل فوراً مع النطاقات الفرعية (بلا SSL): DIWAN_DOMAIN=IP-الخادم.sslip.io sudo -E bash -c \"$(curl -fsSL https://github.com/turkialawlqy/Diwan-ERP/releases/latest/download/install-server.sh)\" مثال: DIWAN_DOMAIN=167.71.196.39.sslip.io. ثم افتح http://167.71.196.39.sslip.io/register. وبعد انتشار نطاقك الحقيقي، انتقل إليه بأمر واحد (يصدر الشهادة ويحوّل كل شيء إلى https، وتبقى المنشآت بأسمائها): DIWAN_DOMAIN=vatrix.app bash /var/www/diwan/deploy/ubuntu/install.sh"},{"p":"دليل إعداد خادم «الديوان» من الصفر","g":"الخوادم والتشغيل","u":"server-setup.html#8-بعد-التثبيت-مباشرة","h":"8. بعد التثبيت مباشرة","t":""},{"p":"دليل إعداد خادم «الديوان» من الصفر","g":"الخوادم والتشغيل","u":"server-setup.html#أ-احفظ-الأسرار-ثم-احذف-ملفها","h":"أ. احفظ الأسرار ثم احذف ملفها","t":"cat /root/diwan-secrets.txt انسخ القيم الثلاث (APP_KEY وDB_PASSWORD وBACKUP_PASSWORD) إلى مدير كلمات المرور، ثم: rm /root/diwan-secrets.txt APP_KEY هو أهم سر: يشفّر مفاتيح أجهزة الفوترة الإلكترونية وأسرار الربط. إن ضاع لا يمكن فك تشفيرها، وتحتاج إعادة ربط الأجهزة. لا تغيّره أبداً بعد التشغيل. وBACKUP_PASSWORD يلزم لفك النسخ الاحتياطية؛ بدونه لا قيمة للنسخ."},{"p":"دليل إعداد خادم «الديوان» من الصفر","g":"الخوادم والتشغيل","u":"server-setup.html#ب-أضف-البريد-إن-تخطيته-أثناء-التثبيت","h":"ب. أضف البريد (إن تخطيته أثناء التثبيت)","t":"nano /var/www/diwan/.env عدّل هذه الأسطر: MAIL_MAILER=smtp MAIL_HOST=smtp.example.com MAIL_PORT=587 MAIL_USERNAME=no-reply@vatrix.app MAIL_PASSWORD='كلمة-مرور-البريد' MAIL_FROM_ADDRESS=no-reply@vatrix.app BACKUP_NOTIFY_EMAIL=you@example.com احفظ، ثم طبّق التغيير: cd /var/www/diwan && sudo -u www-data php artisan optimize && supervisorctl restart 'diwan:*'"},{"p":"دليل إعداد خادم «الديوان» من الصفر","g":"الخوادم والتشغيل","u":"server-setup.html#ج-تأمين-الدخول-إلى-الخادم-موصى-به","h":"ج. تأمين الدخول إلى الخادم (موصى به)","t":"بعد التأكد أن دخولك بمفتاح SSH يعمل، أوقف الدخول بكلمة المرور: sed -i 's/^#\\?PasswordAuthentication .*/PasswordAuthentication no/' /etc/ssh/sshd_config systemctl restart ssh"},{"p":"دليل إعداد خادم «الديوان» من الصفر","g":"الخوادم والتشغيل","u":"server-setup.html#9-النسخ-الاحتياطي-خارج-الخادم","h":"9. النسخ الاحتياطي خارج الخادم","t":"النظام يأخذ نسخة مشفّرة من قاعدة البيانات يومياً على الخادم نفسه. للإنتاج يجب أن تُرفع نسخة أيضاً خارج الخادم، حتى لا تضيع البيانات إن تعطل الخادم. باستخدام DigitalOcean Spaces: Spaces Object Storage ← Create Bucket: اختر نفس المنطقة، واسماً مثل diwan-backups، وRestrict File Listing. API ← Spaces Keys ← Generate New Key: انسخ Key وSecret. أضف إلى /var/www/diwan/.env (مثال لمنطقة fra1): BACKUP_OFFSITE_DISK=offsite BACKUP_S3_KEY=المفتاح BACKUP_S3_SECRET='السر' BACKUP_S3_REGION=fra1 BACKUP_S3_BUCKET=diwan-backups BACKUP_S3_ENDPOINT=https://fra1.digitaloceanspaces.com طبّق وجرّب نسخة فورية: cd /var/www/diwan && sudo -u www-data php artisan optimize sudo -u www-data php artisan erp:backup sudo -u"},{"p":"دليل إعداد خادم «الديوان» من الصفر","g":"الخوادم والتشغيل","u":"server-setup.html#10-الفحص-النهائي-قبل-التشغيل-الفعلي","h":"10. الفحص النهائي قبل التشغيل الفعلي","t":"cd /var/www/diwan && sudo -u www-data php artisan erp:preflight يجب ألا يظهر أي سطر يبدأ بـ «خطأ». الأخطاء المعتادة وحلها: الرسالة الحل HTTPS غير مفروض الشهادة لم تصدر: تأكد من انتشار الـ DNS ثم أعد تشغيل السكربت. MAIL_MAILER لا يرسل بريداً أضف SMTP (القسم 8-ب). BACKUP_PASSWORD غير مضبوط لا يحدث مع السكربت، إلا إن عُدّل .env يدوياً. لا توجد نسخة خارج الخادم (تنبيه) القسم 9. فحص backup: no successful backup (تنبيه) يزول بعد أول نسخة: php artisan erp:backup. وتحقق من صفحة الصحة في المتصفح: https://vatrix.app/health يجب أن تُظهر \"ok\":true (ورمز الاستجابة 200)."},{"p":"دليل إعداد خادم «الديوان» من الصفر","g":"الخوادم والتشغيل","u":"server-setup.html#11-أول-استخدام-مدير-المنصة-والمنشآت","h":"11. أول استخدام: مدير المنصة والمنشآت","t":""},{"p":"دليل إعداد خادم «الديوان» من الصفر","g":"الخوادم والتشغيل","u":"server-setup.html#مدير-المنصة","h":"مدير المنصة","t":"افتح https://vatrix.app/login وادخل بالبريد وكلمة المرور التي أنشأتها في التثبيت. سيُطلب منك تفعيل التحقق الثنائي: اتبع الخطوات في الصفحة (Google Authenticator أو Microsoft Authenticator أو Authy)، واحفظ رموز الاسترداد. من لوحة المنصة تدير المنشآت والاشتراكات والباقات."},{"p":"دليل إعداد خادم «الديوان» من الصفر","g":"الخوادم والتشغيل","u":"server-setup.html#تسجيل-منشأة","h":"تسجيل منشأة","t":"افتح https://vatrix.app/register. أدخل اسم المنشأة، والنطاق الفرعي (مثل diwan)، والدولة، والعملة، وبيانات المدير. تعمل المنشأة على https://diwan.vatrix.app."},{"p":"دليل إعداد خادم «الديوان» من الصفر","g":"الخوادم والتشغيل","u":"server-setup.html#إعدادات-المنشأة-الأولى-داخلها","h":"إعدادات المنشأة الأولى (داخلها)","t":"الإعدادات العامة: الشعار، والرقم الضريبي، والسجل التجاري. الفروع: دولة كل فرع وعملته ورقمه الضريبي. الفوترة الإلكترونية (للسعودية): بيانات البائع والعنوان الوطني، ثم ربط الجهاز برمز OTP من بوابة «فاتورة». المستخدمون والأدوار. البيانات الافتتاحية: العملاء والموردون والأصناف والأرصدة، من شاشة نقل البيانات أو أزرار الاستيراد من Excel."},{"p":"دليل إعداد خادم «الديوان» من الصفر","g":"الخوادم والتشغيل","u":"server-setup.html#12-التحديثات","h":"12. التحديثات","t":"عند صدور تحديث (تعديلات جديدة على الفرع)، على الخادم: sudo bash /var/www/diwan/deploy/ubuntu/update.sh التحديث لا يوقف النظام: المستخدمون يكملون عملهم طوال التحديث. يقوم السكربت بالتالي: يجهّز الإصدار الجديد في مجلد مستقل بجانب الإصدار العامل: يسحب الكود، ويعيد تثبيت المكتبات وبناء الواجهة فقط إن تغيّرت، بأولوية منخفضة كي لا يبطئ الموقع. إن وُجدت ترحيلات لقاعدة البيانات: يأخذ نسخة احتياطية ثم يطبّقها. إن فشلت النسخة يُلغى التحديث ويبقى النظام كما هو. يحوّل النظام إلى الإصدار الجديد في لحظة واحدة: الطلبات الجارية تكتمل على الإصدار القديم، والعمليات الخلفية تُنهي مهمتها الحالية ثم تنتقل. يتحقق من أن النظام يستجيب (/up). إن لم يستجب يرجع تلقائياً للإصدار السابق. يحتفظ بآخر 3 إصدارات ويحذف الأقد"},{"p":"دليل إعداد خادم «الديوان» من الصفر","g":"الخوادم والتشغيل","u":"server-setup.html#13-المراقبة-والصيانة","h":"13. المراقبة والصيانة","t":"ما تراقبه كيف توفر الموقع اربط https://vatrix.app/health بخدمة مراقبة مجانية مثل UptimeRobot، فتنبهك إن توقف الموقع أو العمليات الخلفية أو تقادمت النسخ الاحتياطية (ترد الصفحة بـ 503). العمليات الخلفية supervisorctl status: يجب أن تكون كلها RUNNING. سجل أخطاء النظام tail -n 100 /var/www/diwan/storage/logs/laravel-$(date +%F).log سجل إرسال الفواتير للهيئة tail -n 50 /var/log/diwan/zatca.log مساحة القرص df -h / (أبقِ 20% فارغة على الأقل). تحديثات أمان النظام apt update && apt upgrade -y شهرياً، ثم reboot إن طُلب. الشهادة تتجدد تلقائياً. للتأكد: certbot renew --dry-run."},{"p":"دليل إعداد خادم «الديوان» من الصفر","g":"الخوادم والتشغيل","u":"server-setup.html#14-حل-المشكلات-الشائعة","h":"14. حل المشكلات الشائعة","t":"العَرَض السبب والحل NXDOMAIN عند إصدار الشهادة النطاق لم يُربط بخوادم DigitalOcean بعد، أو غير مفعّل عند المسجّل. تحقق بـ nslookup -type=NS نطاقك، وانتظر الانتشار، ثم أعد تشغيل السكربت. التثبيت يكمل على http ولا يتوقف. JavaScript heap out of memory أثناء البناء ذاكرة الخادم صغيرة جداً. تأكد أن الـ swap مفعّل بالأمر free -h (يجب أن يظهر Swap: 2.0Gi)، أو كبّر الخادم. lock file does not contain a compatible set of packages و php version 8.5 النظام يأتي بـ PHP 8.5. السكربت الحديث يتعامل مع ذلك تلقائياً؛ حدّث نسخة السكربت. والأفضل استخدام Ubuntu 24.04. detected dubious ownership in repository أمر git شُغّل بصلاحية root على مجلد يملكه www-data. شغّل أوامر git هكذا: sudo -u www-data git -C /var/www"},{"p":"دليل إعداد خادم «الديوان» من الصفر","g":"الخوادم والتشغيل","u":"server-setup.html#15-مرجع-سريع-للأوامر","h":"15. مرجع سريع للأوامر","t":"# الانتقال إلى مجلد النظام cd /var/www/diwan # أي أمر artisan يُشغَّل بصلاحية www-data sudo -u www-data php artisan <الأمر> # تحديث النظام sudo bash /var/www/diwan/deploy/ubuntu/update.sh # إعادة تشغيل العمليات الخلفية supervisorctl restart 'diwan:*' # تطبيق تعديل في .env sudo -u www-data php artisan optimize # وضع الصيانة وإلغاؤه sudo -u www-data php artisan down sudo -u www-data php artisan up # نسخة احتياطية فورية والتحقق منها sudo -u www-data php artisan erp:backup sudo -u www-data php artisan erp:backup --verify # الفحص الشامل sudo -u www-data php artisan erp:preflight # إعادة تشغيل الخدمات systemctl restart nginx php*-fpm mysql redis-server"},{"p":"دليل إعداد خادم «الديوان» من الصفر","g":"الخوادم والتشغيل","u":"server-setup.html#مواقع-الملفات-المهمة","h":"مواقع الملفات المهمة","t":"الملف أو المجلد المحتوى /var/www/diwan رابط إلى الإصدار العامل من النظام (كل الأوامر في هذا الدليل تعمل عليه). /var/www/diwan-releases/ الإصدارات (آخر 3). /var/www/diwan-shared/ ما يبقى بين الإصدارات: .env وstorage. /var/www/diwan/.env الإعدادات والأسرار (لا تشاركه أبداً). /var/www/diwan/storage/logs/ سجلات النظام. /var/www/diwan/storage/app/backups/ النسخ الاحتياطية المحلية. /var/log/diwan/ سجلات العمليات الخلفية. /etc/nginx/sites-available/diwan إعداد خادم الويب. /etc/supervisor/conf.d/diwan.conf إعداد العمليات الخلفية. /root/.diwan-install.conf إجابات التثبيت (لإعادة التشغيل)."},{"p":"النشر والتشغيل","g":"الخوادم والتشغيل","u":"deployment.html","h":"النشر والتشغيل","t":"للتثبيت دون خبرة تقنية (جهاز ويندوز أو ماك أو لينكس في المكتب، أو خادم): ابدأ من تثبيت «الديوان»: من أين أبدأ؟. هذا الدليل مرجع تقني للمطورين ومديري الخوادم."},{"p":"النشر والتشغيل","g":"الخوادم والتشغيل","u":"deployment.html#المتطلبات","h":"المتطلبات","t":"PHP 8.2+ بالامتدادات: pdo_mysql mbstring intl openssl zip bcmath gd xml dom. MySQL 8.0+ (أو MariaDB 10.6+)، وRedis 6+. Node 20 للبناء فقط، وNginx، وSupervisor."},{"p":"النشر والتشغيل","g":"الخوادم والتشغيل","u":"deployment.html#أول-تشغيل-إنتاجي-خطوة-بخطوة","h":"أول تشغيل إنتاجي (خطوة بخطوة)","t":"الخادم: أنشئ قاعدة MySQL ومستخدماً لها، وثبّت Redis وNginx وSupervisor (انظر المتطلبات). الكود: git clone <repo> /var/www/diwan && cd /var/www/diwan git checkout stable # فرع/وسم الإصدارات المستقرة، لا فرع التطوير composer install --no-dev --optimize-autoloader npm ci && npm run build الإعدادات: انسخ القالب: cp .env.production.example .env. املأ كل قيمة فارغة: قاعدة البيانات، البريد، BACKUP_PASSWORD، حساب التخزين الخارجي. ثم: php artisan key:generate. احفظ APP_KEY وBACKUP_PASSWORD في مخزن أسرار خارج الخادم. قاعدة البيانات: php artisan migrate --force --seed. في الإنتاج يُنشئ المُبذِر الباقات فقط، بلا شركة تجريبية ولا كلمات مرور. مدير المنصة: php artisan erp:create-super-admin you@example.com"},{"p":"النشر والتشغيل","g":"الخوادم والتشغيل","u":"deployment.html#تثبيت-سريع-على-خادم-ubuntu-واحد-digitalocean","h":"تثبيت سريع على خادم Ubuntu واحد (DigitalOcean)","t":"الدليل الكامل خطوة بخطوة (من إنشاء الخادم حتى أول منشأة، مع حل المشكلات): دليل إعداد خادم «الديوان» من الصفر. سكربت يثبّت كل شيء على خادم واحد، ويصلح حتى لخادم صغير (512MB، إذ يضيف 2GB swap): Nginx وPHP-FPM وMySQL وRedis وSupervisor، والكود من GitHub، والواجهة، وقاعدة البيانات، ومدير المنصة، وشهادة SSL للنطاق ونطاقاته الفرعية. قبل التشغيل (مرة واحدة): DNS في DigitalOcean: أضف النطاق من Networking ← Domains. غيّر خوادم الأسماء عند مسجّل النطاق إلى ns1.digitalocean.com وns2.digitalocean.com وns3.digitalocean.com. أضف سجلين: A @ → IP الخادم وA * → IP الخادم. رمز API: أنشئه من API ← Generate New Token بصلاحية Write. يُستخدم لإصدار شهادة *.النطاق وتجديدها تلقائياً. التشغيل (بصلاحية root على الخاد"},{"p":"النشر والتشغيل","g":"الخوادم والتشغيل","u":"deployment.html#الإعدادات-الأساسية-env","h":"الإعدادات الأساسية (.env)","t":"القالب الكامل في .env.production.example. أهم القيم: APP_ENV=production APP_DEBUG=false APP_URL=https://diwan.io APP_DOMAIN=diwan.io # النطاق المركزي؛ المنشآت على {subdomain}.diwan.io TENANCY_ENFORCE_SUBDOMAIN=true TENANCY_ALLOW_DEV_OVERRIDE=false # لا تسمح بـ ?tenant= في الإنتاج SESSION_DOMAIN=null # كوكي مستقلة لكل نطاق فرعي (لا تجعلها .diwan.io) SESSION_SECURE_COOKIE=true SESSION_ENCRYPT=true DB_CONNECTION=mysql CACHE_STORE=redis SESSION_DRIVER=redis QUEUE_CONNECTION=redis TRUSTED_PROXIES=10.0.0.0/8 # عند وجود موازن أحمال MAIL_MAILER=smtp APP_TIMEZONE=Asia/Riyadh # تواريخ المستندات والترقيم والتقارير TENANCY_REJECT_UNKNOWN_HOSTS=true # يرفض Host مزوّراً (روابط إعادة كلمة المرور) BACKUP_PA"},{"p":"النشر والتشغيل","g":"الخوادم والتشغيل","u":"deployment.html#dns-وشهادات-ssl","h":"DNS وشهادات SSL","t":"السجلات: A diwan.io → IP A *.diwan.io → IP (wildcard) A admin.diwan.io → IP الشهادة: شهادة wildcard عبر DNS-01، مثلاً: certbot certonly --dns-<provider> -d diwan.io -d '*.diwan.io'. النطاقات الخاصة للعملاء: يضيف العميل سجل CNAME إلى {subdomain}.diwan.io وسجل TXT _diwan-verify من صفحة الاشتراك. لا يُخدم النطاق قبل التحقق. أصدر شهادته عبر HTTP-01 أو استخدم on-demand TLS في Caddy."},{"p":"النشر والتشغيل","g":"الخوادم والتشغيل","u":"deployment.html#nginx","h":"Nginx","t":"انظر deploy/nginx.conf."},{"p":"النشر والتشغيل","g":"الخوادم والتشغيل","u":"deployment.html#الطوابير-والمجدول","h":"الطوابير والمجدول","t":"انظر deploy/supervisor.conf. الطوابير المستخدمة: الطابور الاستخدام zatca الاعتماد المسبق والإبلاغ لدى هيئة الزكاة (مهلة الإبلاغ 24 ساعة) webhooks إرسال Webhooks exports نسخ بيانات المنشآت default الإشعارات والبريد المُجدول يعمل كبرنامج diwan-scheduler في الملف نفسه (schedule:work). أو بدلاً منه سطر cron: * * * * * cd /var/www/diwan && php artisan schedule:run >> /dev/null 2>&1 بدون المُجدول لا تعمل أي من المهام في الجدول التالي، ومنها النسخ الاحتياطي والإبلاغ لهيئة الزكاة. يكتب المُجدول نبضاً كل دقيقة يقرؤه /health. المهمة الموعد الوظيفة erp:zatca-submit كل 10 دقائق إعادة جدولة المستندات المعلقة أو المتعثرة erp:alerts يومياً 06:50 ملخص التنبيهات erp:accounting-schedules recurring يومياً القي"},{"p":"النشر والتشغيل","g":"الخوادم والتشغيل","u":"deployment.html#ملاحظات-بيئة-التشغيل","h":"ملاحظات بيئة التشغيل","t":"بعد التحديث: شغّل php artisan erp:sync-permissions، لإضافة صلاحيات الفواتير الدورية ولوحات القيادة للأدوار. ثم شغّل php artisan erp:accounting provision مرة واحدة لإضافة الحسابات الجديدة في دليل الحسابات للمنشآت القائمة، مثل حساب «أرباح وخسائر فروق العملة». ستظهر رسالة واضحة عند سداد بعملة أجنبية إن لم يُضف الحساب. شعارات المنشآت: يعرضها النظام عبر المسار /company/logo، فلا تحتاج php artisan storage:link. يبقى الأمر مفيداً لأي ملفات عامة أخرى. Windows (Laragon / XAMPP): إنشاء مفاتيح أجهزة ZATCA لا يعتمد على openssl.cnf الخاص بالنظام، لأن النظام يولّد ملف إعداد خاصاً به. اللغة الافتراضية: العربية (APP_LOCALE=ar)، ورسائل التحقق مترجمة في lang/ar."},{"p":"النشر والتشغيل","g":"الخوادم والتشغيل","u":"deployment.html#خطوات-النشر","h":"خطوات النشر","t":"php artisan erp:backup --tag=preupdate # نسخة قبل التحديث خارج التدوير اليومي php artisan down --retry=60 git pull # من فرع/وسم stable composer install --no-dev --optimize-autoloader npm ci && npm run build php artisan migrate --force # إن فشل: ابقَ في الصيانة واستعد النسخة (انظر الاستعادة) php artisan erp:sync-permissions php artisan erp:accounting provision # الحسابات الجديدة للمنشآت القائمة php artisan optimize php artisan queue:restart php artisan up php artisan erp:preflight"},{"p":"النشر والتشغيل","g":"الخوادم والتشغيل","u":"deployment.html#النسخ-الاحتياطي","h":"النسخ الاحتياطي","t":"النظام ينسخ نفسه تلقائياً بأمر erp:backup، المجدول يومياً الساعة 02:40، مع اختبار استعادة كل أحد. يتطلب ذلك تشغيل المجدول (schedule:run)."},{"p":"النشر والتشغيل","g":"الخوادم والتشغيل","u":"deployment.html#محتوى-النسخة","h":"محتوى النسخة","t":"قاعدة البيانات: mysqldump --single-transaction أو نسخة SQLite. الملفات: storage/app/public وstorage/app/private. ملف manifest.json: عدد سجلات كل جدول. التشفير: الأرشيف مشفّر بـ AES-256 بكلمة مرور BACKUP_PASSWORD. احفظ كلمة المرور خارج الخادم، فبدونها لا يمكن الاستعادة."},{"p":"النشر والتشغيل","g":"الخوادم والتشغيل","u":"deployment.html#الإعدادات-env","h":"الإعدادات (.env)","t":"المتغير الوصف BACKUP_PASSWORD كلمة مرور التشفير (إلزامية عملياً). BACKUP_DISK القرص الأساسي. الافتراضي backups (storage/app/backups). BACKUP_OFFSITE_DISK offsite لنسخ كل نسخة إلى تخزين S3 متوافق: AWS أو Wasabi أو Backblaze أو MinIO. الإعدادات في BACKUP_S3_*. BACKUP_KEEP_DAILY / _WEEKLY / _MONTHLY الاحتفاظ. الافتراضي 7 يومية و4 أسبوعية و6 شهرية. BACKUP_VERIFY_DATABASE قاعدة MySQL فارغة مخصصة لاختبار الاستعادة الكامل (تُحذف وتُنشأ في كل اختبار). بدونها يكتفي الاختبار بفحص بنية الملف. BACKUP_NOTIFY_EMAIL بريد يُنبَّه عند فشل النسخ أو الاختبار."},{"p":"النشر والتشغيل","g":"الخوادم والتشغيل","u":"deployment.html#المتابعة","h":"المتابعة","t":"من الواجهة: صفحة «النسخ الاحتياطي» في لوحة مدير المنصة، وفيها آخر نسخة واختبار الاستعادة والملفات، وزر نسخ فوري. يدوياً: php artisan erp:backup لإنشاء نسخة، وphp artisan erp:backup --verify لاختبار الاستعادة."},{"p":"النشر والتشغيل","g":"الخوادم والتشغيل","u":"deployment.html#الاستعادة","h":"الاستعادة","t":"php artisan erp:backup --tag=prerestore # احتياطاً، نسخة من الوضع الحالي php artisan erp:restore diwan-backup-YYYY-MM-DD-HHMMSS.zip # من القرص الأساسي php artisan erp:restore diwan-backup-YYYY-MM-DD-HHMMSS.zip --disk=offsite # من النسخة الخارجية ما يفعله الأمر: يضع الموقع في الصيانة. يفك الأرشيف بـ BACKUP_PASSWORD. يستعيد قاعدة البيانات والملفات المرفوعة. يشغّل الترحيل، ثم يعيد الموقع. على خادم جديد: الأرشيف يحتوي APP_KEY الأصلي، وبدونه لا تُقرأ مفاتيح أجهزة ZATCA. إن اختلف عن الحالي يطبعه الأمر لتضعه في .env. يدوياً بدون الأمر: 7z x <file> -p\"$BACKUP_PASSWORD\". mysql diwan < database.sql. انسخ files/public وfiles/private إلى storage/app/. php artisan optimize:clear."},{"p":"النشر والتشغيل","g":"الخوادم والتشغيل","u":"deployment.html#نسخة-منشأة-واحدة","h":"نسخة منشأة واحدة","t":"يستطيع مالك المنشأة طلب نسخة كاملة من بياناته (CSV مضغوط) من صفحة الاشتراك."},{"p":"النشر والتشغيل","g":"الخوادم والتشغيل","u":"deployment.html#التحقق-الثنائي-2fa","h":"التحقق الثنائي (2FA)","t":"مدير المنصة: إلزامي له دائماً. يمكن تعطيله فقط للعروض المحلية بـ TWO_FACTOR_SUPER_ADMIN=false. مدير المنشأة: يحدد الأدوار الملزمة به من «الإعدادات ← النظام ← الأمان». أي مستخدم: يستطيع تفعيله من «الملف الشخصي» عبر تطبيق مصادقة. يحصل عند التفعيل على 8 رموز استرداد، كل رمز يُستخدم مرة واحدة. رموز التطبيق: تعتمد على الوقت، لذلك يجب أن تكون ساعة الخادم مضبوطة (NTP)."},{"p":"النشر والتشغيل","g":"الخوادم والتشغيل","u":"deployment.html#المراقبة-والأداء","h":"المراقبة والأداء","t":"الصحة: المسار /up لفحص الصحة. الفهارس: كل الجداول مفهرسة بـ company_id مع أعمدة البحث والتواريخ. الأرصدة: ميزان المراجعة يقرأ من أرصدة شهرية مجمعة (account_balances). يُعاد بناؤها عند الحاجة بـ php artisan erp:accounting rebuild-balances. اختبار الحمل: php artisan erp:load-test ينشئ بيانات ضخمة ويقيس زمن التقارير. التزامن: الترقيم والمخزون وسلسلة الفواتير الإلكترونية محمية بأقفال الصفوف SELECT ... FOR UPDATE. جُرّب ذلك على MySQL 8 بأربع عمليات متزامنة: لا أرقام مكررة، والمخزون والقيود متطابقة."},{"p":"سياسة الاحتفاظ بالبيانات وإنهاء الاشتراك","g":"الخوادم والتشغيل","u":"data-retention.html","h":"سياسة الاحتفاظ بالبيانات وإنهاء الاشتراك","t":"وثيقة تشغيلية لمدير المنصة. راجعها قانونياً، وأضف خلاصتها إلى الشروط والأحكام."},{"p":"سياسة الاحتفاظ بالبيانات وإنهاء الاشتراك","g":"الخوادم والتشغيل","u":"data-retention.html#مدد-الاحتفاظ","h":"مدد الاحتفاظ","t":"البيانات المدة السبب الفواتير الإلكترونية وملفات XML وQR وسجل الإرسال للهيئة 6 سنوات على الأقل من نهاية السنة المالية متطلبات هيئة الزكاة والضريبة والجمارك القيود والدفاتر المحاسبية والمستندات المؤيدة 10 سنوات نظام الدفاتر التجارية بيانات الموظفين والرواتب مدة العلاقة التعاقدية + 10 سنوات نظام العمل والتأمينات سجل التدقيق وسجل دخول المستخدمين سنتان الأمن والتحقيق في الحوادث النسخ الاحتياطية 7 يومية، و4 أسبوعية، و6 شهرية (BACKUP_KEEP_*) الاستعادة من الأعطال"},{"p":"سياسة الاحتفاظ بالبيانات وإنهاء الاشتراك","g":"الخوادم والتشغيل","u":"data-retention.html#عند-انتهاء-الاشتراك","h":"عند انتهاء الاشتراك","t":"فترة سماح (saas.grace_days، 7 أيام افتراضياً) يعمل فيها النظام كاملاً. بعدها يصبح الحساب للقراءة فقط. يستطيع المالك الدخول وطباعة المستندات وتصدير بياناته، ولا يستطيع إنشاء مستندات جديدة. تبقى البيانات محفوظة طوال المدد النظامية أعلاه."},{"p":"سياسة الاحتفاظ بالبيانات وإنهاء الاشتراك","g":"الخوادم والتشغيل","u":"data-retention.html#عند-طلب-المنشأة-المغادرة","h":"عند طلب المنشأة المغادرة","t":"يصدّر المالك نسخة كاملة من بياناته من «الاشتراك ← تصدير البيانات». يمكن لمدير المنصة فعل ذلك عبر الدخول إلى المنشأة. يوقف مدير المنصة المنشأة من صفحتها في لوحة المنصة (الحالة: «موقوف»)، مع ذكر السبب. حذف البيانات: ما يُحذف بعد انتهاء المدد النظامية: البيانات التشغيلية والمستخدمون. ما يُحتفظ به حتى نهاية المدة: الفواتير الإلكترونية والقيود. عند طلب صريح بالحذف المبكر: يُوثَّق الطلب، ويُبلَّغ العميل بأن الأنظمة تُلزم بالاحتفاظ بالسجلات الضريبية."},{"p":"سياسة الاحتفاظ بالبيانات وإنهاء الاشتراك","g":"الخوادم والتشغيل","u":"data-retention.html#طلبات-أصحاب-البيانات-نظام-حماية-البيانات-الشخصية","h":"طلبات أصحاب البيانات (نظام حماية البيانات الشخصية)","t":"العميل هو جهة التحكم: الطلبات المتعلقة بعملاء المنشأة أو موظفيها تُحال إلى المنشأة نفسها. طلبات المستخدمين عن حساباتهم: تُنفَّذ خلال 30 يوماً، وتشمل العلم والوصول والتصحيح والإتلاف حيث لا يمنع نظام."},{"p":"الفوترة الإلكترونية (فاتورة)","g":"الوحدات والميزات","u":"zatca.html#المرحلة-الأولى","h":"المرحلة الأولى","t":"إذا لم يكن للمنشأة جهاز مربوط، تحمل كل فاتورة وإشعار رمز QR بالوسوم 1–5: اسم البائع، الرقم الضريبي، الوقت، الإجمالي، الضريبة."},{"p":"الفوترة الإلكترونية (فاتورة)","g":"الوحدات والميزات","u":"zatca.html#المرحلة-الثانية-الربط-والتكامل","h":"المرحلة الثانية (الربط والتكامل)","t":""},{"p":"الفوترة الإلكترونية (فاتورة)","g":"الوحدات والميزات","u":"zatca.html#خطوات-الربط","h":"خطوات الربط","t":"يُنفذ الربط من شاشة الإعدادات ← الفوترة الإلكترونية: بيانات البائع: الرقم الضريبي (15 رقماً يبدأ وينتهي بـ 3) والسجل التجاري. العنوان الوطني: الشارع، رقم المبنى (4 أرقام)، الحي، المدينة، الرمز البريدي (5 أرقام). جهاز جديد (EGS): يُنشأ مفتاح ECDSA على secp256k1، ويُحفظ مشفراً بـ APP_KEY. يُنشأ CSR بصيغة الهيئة: قالب الشهادة حسب البيئة، وSN=1-Diwan|2-ERP|3-uuid (اسم الحل من ZATCA_SOLUTION_NAME)، وUID الرقم الضريبي، وtitle لأنواع الفواتير. رمز OTP: من بوابة فاتورة (fatoora.zatca.gov.sa) ← ربط الجهاز. ينفذ النظام آلياً: طلب شهادة الامتثال (Compliance CSID). إرسال 6 نماذج امتثال موقعة (فاتورة ودائن ومدين، لكل من الضريبية والمبسطة). طلب الشهادة الإنتاجية (Production CSID). التفعيل: بعدها تُوقّع كل"},{"p":"الفوترة الإلكترونية (فاتورة)","g":"الوحدات والميزات","u":"zatca.html#تفاصيل-التنفيذ","h":"تفاصيل التنفيذ","t":"المكوّن الوظيفة UblInvoiceBuilder UBL 2.1 (ملف KSA): الأطراف والعنوان الوطني، خصومات البنود، الضريبة لكل فئة، ICV وPIH، مرجع الفاتورة الأصلية وسبب الإشعار InvoiceSigner تجزئة SHA-256 للمستند بعد إزالة UBLExtensions وcac:Signature ومرجع QR، توقيع ECDSA-SHA256، خصائص XAdES، رمز QR بالوسوم 1–9، ودالة verify() للتحقق EInvoiceManager يقفل صف الجهاز لضمان تسلسل ICV وسلسلة PIH (أول فاتورة: تجزئة \"0\") ZatcaClient واجهات البوابة V2 للبيئات الثلاث"},{"p":"الفوترة الإلكترونية (فاتورة)","g":"الوحدات والميزات","u":"zatca.html#البيئات","h":"البيئات","t":"البيئة الوصف sandbox بوابة المطورين، للتجربة simulation المحاكاة production الإنتاج اختر البيئة عند إنشاء الجهاز. ابدأ دائماً بـ sandbox أو simulation."},{"p":"الفوترة الإلكترونية (فاتورة)","g":"الوحدات والميزات","u":"zatca.html#ملاحظات-مهمة","h":"ملاحظات مهمة","t":"قبل الإنتاج: الاختبارات الآلية تتحقق من صحة التوقيع والتسلسل والبنية مقابل بوابة مُحاكاة (CA تجريبية). لم يُجرَ إرسال حقيقي لهيئة الزكاة في هذه البيئة. قبل الإنتاج: أنجز الربط على بيئة simulation بـ OTP حقيقي. افحص نماذج XML بأداة التحقق في بوابة المطورين أو SDK الرسمي. فاتورة مرفوضة: لا تُحذف. تُصحح بإشعار دائن/مدين. التقريب: ضريبة الفاتورة في XML تُحسب لكل فئة ضريبية مقربة (BR-CO). قد تختلف بهللة عن مجموع ضرائب البنود المخزن. الفئات الضريبية وأسباب الإعفاء: لكل صنف فئة (S قياسي، Z صفري، E معفى، O خارج النطاق) وسبب إعفاء رسمي (VATEX-…) يُضبط في بطاقة الصنف. الأولوية: ما يُرسل في السطر، ثم إعداد الصنف، ثم الافتراضي الذي تضبطه المنشأة من شاشة «الفوترة الإلكترونية ← الإعدادات الضريبية». غياب ا"},{"p":"الفوترة الإلكترونية (فاتورة)","g":"الوحدات والميزات","u":"zatca.html#ملف-pdf-للفاتورة-pdfa-3","h":"ملف PDF للفاتورة (PDF/A-3)","t":"مكان التنزيل: زر «PDF» في صفحات الفاتورة والإشعار الدائن. المحتوى: ملف PDF/A-3 يضمّ ملف XML الموقّع (UBL 2.1) كمرفق مرتبط (AFRelationship=Data) مع رمز QR. هذه صيغة الفاتورة المجمّعة التي تصفها الهيئة لمشاركة الفواتير بين المنشآت. أي نسخة XML: المعتمدة من الهيئة (cleared_xml) إن وُجدت، وإلا الموقّعة محلياً. التحقق من المرفق: pdfdetach -list invoice.pdf."},{"p":"التصنيع والمصانع","g":"الوحدات والميزات","u":"manufacturing.html","h":"التصنيع والمصانع","t":"وحدة «التصنيع» في القائمة الجانبية. تخدم نوعين من المصانع: تصنيع حسب أمر إنتاج (مصانع الأثاث والمعادن والملابس...): لكل أمر مواد وعمليات وتكلفة فعلية. تصنيع مستمر (الأغذية والبلاستيك...): خط متصل بمراحل، وتُحسب تكلفة المرحلة في كل فترة."},{"p":"التصنيع والمصانع","g":"الوحدات والميزات","u":"manufacturing.html#البداية-في-ست-خطوات","h":"البداية في ست خطوات","t":"المنتجات: أنشئ الخامات والمنتجات التامة من «المخزون ← المنتجات» وأدخل رصيد الخامات. مراكز العمل: لكل آلة أو خط أو ورشة: طاقتها اليومية وكفاءتها وتكلفة ساعة الأجور وساعة المصروفات غير المباشرة. مسار التشغيل: تسلسل العمليات (قص ثم كبس ثم تجميع...) ووقت التجهيز ووقت تشغيل الوحدة في كل مركز. قائمة المواد (BOM): مكونات المنتج وكمياتها وهالك كل مكوّن، وربطها بالمسار. لكل منتج إصدارات وواحد افتراضي. أمر الإنتاج: يحسب المواد والعمليات تلقائياً. أفرج عنه، ثم اصرف المواد وسجّل الوقت واستلم المنتج. أغلق الأمر: يظهر ما بقي تحت التشغيل كفروقات تصنيع."},{"p":"التصنيع والمصانع","g":"الوحدات والميزات","u":"manufacturing.html#القيود-المحاسبية-تلقائية","h":"القيود المحاسبية (تلقائية)","t":"الحدث المدين الدائن صرف مواد لأمر إنتاج تحت التشغيل المخزون إرجاع مواد المخزون إنتاج تحت التشغيل وقت تشغيل إنتاج تحت التشغيل أجور تصنيع محمّلة + مصروفات تصنيع محمّلة استلام منتج تام المخزون إنتاج تحت التشغيل هالك غير طبيعي هالك التصنيع غير الطبيعي إنتاج تحت التشغيل إغلاق الأمر (الباقي) فروقات التصنيع إنتاج تحت التشغيل الأجور والمصروفات الفعلية تبقى في حساباتها (الرواتب، الكهرباء...)، و«المحمّلة» حسابان دائنان يخصمان نصيب الإنتاج منها فتدخل تكلفة المنتج بدل المصروف. تُضاف الحسابات (1133 و516-519) تلقائياً لكل منشأة عند التحديث."},{"p":"التصنيع والمصانع","g":"الوحدات والميزات","u":"manufacturing.html#تكلفة-المنتج-التام","h":"تكلفة المنتج التام","t":"عند كل استلام: (مواد + أجور + مصروفات − ما حُوِّل سابقاً) × (الكمية المستلمة ÷ المتبقي من الأمر). آخر استلام يأخذ ما بقي كله فلا يتبقى فرق تقريب. الهالك الطبيعي تتحمله الوحدات السليمة. الهالك «غير الطبيعي» يُحمَّل خسارة منفصلة."},{"p":"التصنيع والمصانع","g":"الوحدات والميزات","u":"manufacturing.html#التصنيع-المستمر-تكلفة-المراحل","h":"التصنيع المستمر (تكلفة المراحل)","t":"لكل مرحلة فترة (شهر مثلاً): تُصرف المواد وتُضاف تكلفة التحويل، وعند الإغلاق تُدخل الوحدات المكتملة والوحدات التي بقيت تحت التشغيل ونسبة إنجازها. الطريقة: المتوسط المرجح بالوحدات المعادلة لثلاثة عناصر: محوّل من مرحلة سابقة (100%) ومواد مباشرة وتحويل. ما بقي تحت التشغيل ينتقل أول الفترة التالية. المرحلة الأخيرة تستلم المنتج في المخزون، وغيرها تمرّر تكلفتها للمرحلة التالية (افتح فترة التالية أولاً)."},{"p":"التصنيع والمصانع","g":"الوحدات والميزات","u":"manufacturing.html#تخطيط-الاحتياجات-mrp","h":"تخطيط الاحتياجات (MRP)","t":"يقارن الطلب (أوامر بيع مؤكدة غير مسلَّمة، مواد أوامر إنتاج مفتوحة، حد إعادة الطلب) بالمتاح (مخزون وأوامر شراء وإنتاج وتصنيع لدى الغير مفتوحة). ما كان له قائمة مواد يُقترح تصنيعه وتتفكك مكوناته على كل المستويات، وغيره يُقترح شراؤه. حوّل اقتراحات الشراء إلى طلب شراء واحد والتصنيع إلى أوامر إنتاج. «مهلة التوريد» تُضبط في بطاقة الصنف."},{"p":"التصنيع والمصانع","g":"الوحدات والميزات","u":"manufacturing.html#الجودة","h":"الجودة","t":"أنشئ خطة جودة لمنتج (أو لكل المنتجات) ببنود سليم/معيب أو قياس بين حدين. عند استلام الإنتاج يُحجز المنتج خارج المخزون ويُفتح فحص: المقبول يدخل المخزون بنصيبه من التكلفة، والمرفوض المُتلَف يُحمَّل خسارة، وما أُعيد تشغيله يبقى تحت التشغيل. الفحص اليدوي متاح للمشتريات (تسجيل فقط)."},{"p":"التصنيع والمصانع","g":"الوحدات والميزات","u":"manufacturing.html#التصنيع-لدى-الغير","h":"التصنيع لدى الغير","t":"أمر لمورد: تُرسل الخامات إلى مستودع يمثل «عند المصنّع» (تبقى في مخزونك)، وعند الاستلام: المنتج التام = خامات مستهلكة + أجر التصنيع، والأجر دائن للمورد في الذمم الدائنة."},{"p":"التصنيع والمصانع","g":"الوحدات والميزات","u":"manufacturing.html#ما-لا-تغطيه-هذه-النسخة","h":"ما لا تغطيه هذه النسخة","t":"المنتجات الثانوية (By-products) ومشتركات الإنتاج. الجدولة اللانهائية/المحدودة التلقائية؛ الطاقة تُعرض ولا تُعيد ترتيب الأوامر. أجور العمال الفعلية بالساعة من الحضور؛ التحميل بمعدل مركز العمل. إرسال مواد لمقاول لعملية واحدة داخل أمر إنتاج (التصنيع لدى الغير يكون لأمر كامل)."},{"p":"الواجهة البرمجية (REST API v1)","g":"للمطوّرين","u":"api.html","h":"الواجهة البرمجية (REST API v1)","t":"المصادقة: Bearer token يُنشأ من الإعدادات ← الربط البرمجي. النطاق: الرمز مقيد بمنشأة صاحبه وبالصلاحيات المختارة له. حد الطلبات: 120 طلباً في الدقيقة لكل مستخدم. العنوان الأساسي: https://{subdomain}.diwan.io/api/v1. curl -H \"Authorization: Bearer $TOKEN\" -H \"Accept: application/json\" https://anas.diwan.io/api/v1/customers?search=أحمد الطريقة المسار الصلاحية الوصف GET /me — المستخدم والمنشأة وصلاحيات الرمز GET /customers?search=&page=&per_page= sales.clients.view قائمة العملاء GET /customers/{id} sales.clients.view عميل POST /customers sales.clients.create إنشاء عميل GET /products?search= inventory.products.view الأصناف GET /products/{id} inventory.products.view صنف مع أرصدته في كل مستودع GET "},{"p":"الواجهة البرمجية (REST API v1)","g":"للمطوّرين","u":"api.html#مثال-إصدار-فاتورة","h":"مثال: إصدار فاتورة","t":"POST /api/v1/invoices { \"customer_id\": 12, \"invoice_date\": \"2026-10-05\", \"invoice_type\": \"standard\", \"payment_status\": \"unpaid\", \"items\": [ {\"product_id\": 5, \"item_name\": \"قطعة غيار\", \"quantity\": 2, \"unit_price\": 150, \"tax_rate\": 15} ] }"},{"p":"الواجهة البرمجية (REST API v1)","g":"للمطوّرين","u":"api.html#الأخطاء","h":"الأخطاء","t":"الرمز المعنى 401 رمز غير صالح 403 صلاحية غير ممنوحة للرمز أو للمستخدم، أو وحدة خارج الباقة 402 انتهى الاشتراك (قراءة فقط) 404 السجل غير موجود في منشأتك 422 أخطاء التحقق في errors"},{"p":"الواجهة البرمجية (REST API v1)","g":"للمطوّرين","u":"api.html#webhooks","h":"Webhooks","t":"الإنشاء: من الإعدادات ← الربط البرمجي. يُعطى مفتاح التوقيع whsec_... مرة واحدة. الأحداث: invoice.created، payment.received، credit_note.created، zatca.status_changed."},{"p":"الواجهة البرمجية (REST API v1)","g":"للمطوّرين","u":"api.html#شكل-الطلب","h":"شكل الطلب","t":"POST <your url> X-Diwan-Event: invoice.created X-Diwan-Delivery: <uuid> X-Diwan-Timestamp: 1791234567 X-Diwan-Signature: sha256=<hex> {\"id\":\"<uuid>\",\"event\":\"invoice.created\",\"created_at\":\"...\",\"data\":{...}}"},{"p":"الواجهة البرمجية (REST API v1)","g":"للمطوّرين","u":"api.html#التحقق-من-التوقيع","h":"التحقق من التوقيع","t":"$expected = 'sha256='.hash_hmac('sha256', $timestamp.'.'.$rawBody, $secret); hash_equals($expected, $signatureHeader); // ارفض الطلبات الأقدم من 5 دقائق"},{"p":"الواجهة البرمجية (REST API v1)","g":"للمطوّرين","u":"api.html#قواعد-التسليم","h":"قواعد التسليم","t":"إعادة المحاولة: تُعاد المحاولة حتى 5 مرات، بعد 30 ثانية ثم 2 دقيقة ثم 10 دقائق ثم ساعة. الإيقاف التلقائي: يُوقف الـ endpoint تلقائياً بعد 50 فشلاً متتالياً. العناوين المقبولة: عناوين HTTPS عامة فقط؛ تُرفض عناوين الشبكات الداخلية."},{"p":"المعمارية","g":"للمطوّرين","u":"architecture.html#تعدد-المنشآت","h":"تعدد المنشآت","t":"قاعدة البيانات: قاعدة واحدة، وكل جدول خاص بمنشأة يحمل company_id (بما فيها جداول البنود). الفهارس تبدأ بـ company_id. ResolveTenant: يحدد المنشأة من النطاق الفرعي أو النطاق الخاص الموثق، ويرفض المستخدم إن لم يكن من نفس المنشأة. مالك المنصة يدخل منشأة فقط في وضع المساندة، بسبب مسجل ومدة محددة. BelongsToCompany: نطاق عام يفشل مغلقاً: لا مستأجر يعني لا صفوف، ويملأ company_id تلقائياً. المهام والأوامر تعمل داخل TenantManager::runAs($company, fn). tenant_exists:table,id: تتحقق أن كل معرف مرسل من نفس المنشأة. BranchScoped: المستخدم المرتبط بفرع يرى مستندات فرعه فقط، ما لم يملك admin.data_scope.manage."},{"p":"المعمارية","g":"للمطوّرين","u":"architecture.html#الصلاحيات","h":"الصلاحيات","t":"السجل: config/erp_permissions.php هو السجل الوحيد للوحدات والموارد والإجراءات والأدوار الافتراضية، ولخريطة المسارات (اسم المسار ← الصلاحية). التطبيق: AuthorizeRoutePermission يطبق الخريطة على كل مسار، والمسار غير الموجود في الخريطة مرفوض. اختبار آلي يضمن أن كل مسار مربوط. رموز API: يجب أن يملك الرمز الصلاحية، وأن يملكها صاحبه كذلك. الباقة: EnsurePlanAccess يرفض الوحدات غير المشمولة، ويجعل الاشتراك المنتهي للعرض فقط. حدود الباقة تُفرض عند إنشاء السجلات من أي مدخل."},{"p":"المعمارية","g":"للمطوّرين","u":"architecture.html#المحاسبة","h":"المحاسبة","t":"PostingService: الطريق الوحيد للكتابة في الأستاذ. القيد متوازن إلزامياً، على حسابات فرعية فقط، وفي فترة مفتوحة. الإلغاء بقيد عكسي لا بالحذف. يحدّث الأرصدة الشهرية المجمعة وأرصدة الحسابات. AccountMap: يربط أدوار الحسابات (receivables, inventory, grni…) بحسابات المنشأة."},{"p":"المعمارية","g":"للمطوّرين","u":"architecture.html#قوالب-القيود","h":"قوالب القيود","t":"المستند مدين دائن فاتورة مبيعات العملاء/النقدية، تكلفة المبيعات المبيعات، ضريبة المخرجات، المخزون إذن تسليم تكلفة المبيعات المخزون فاتورة من إذن تسليم العملاء المبيعات، ضريبة المخرجات مرتجع مبيعات مردودات المبيعات، ضريبة المخرجات، المخزون العملاء/النقدية، تكلفة المبيعات إشعار مدين العملاء المبيعات، ضريبة المخرجات سند قبض النقدية/البنك العملاء استلام بضاعة GRN المخزون بضاعة مستلمة لم تصل فواتيرها فاتورة مورد من الاستلام بضاعة مستلمة، فرق السعر، ضريبة المدخلات الموردون/النقدية مرتجع مشتريات الموردون/النقدية المخزون، فرق التكلفة، ضريبة المدخلات تكاليف إضافية المخزون (للكمية المتبقية)، تكلفة المبيعات (للمباع) الموردون/النقدية دفعة مقدمة من عميل مشروع النقدية دفعات مقدمة من العملاء، ضريبة المخرجا"},{"p":"المعمارية","g":"للمطوّرين","u":"architecture.html#المخزون","h":"المخزون","t":"السجل: StockService يكتب حركة لكل دخول وخروج (stock_movements)، ويحدّث inventory_stocks تحت قفل صف. التكلفة: متوسط مرجح على مستوى المنشأة، أو FIFO بطبقات stock_layers. التتبع: الدفعات تُصرف بالأقرب انتهاءً (FEFO)، والأرقام التسلسلية فريدة لكل صنف. المستندات: DocumentStock يحول الوحدات ويختار المستودع الافتراضي."},{"p":"المعمارية","g":"للمطوّرين","u":"architecture.html#الترقيم","h":"الترقيم","t":"DocumentNumberService + جدول document_sequences: القفل: يقفل صف العداد داخل المعاملة، فلا تتكرر الأرقام مع التزامن. البادئات: قابلة للتخصيص لكل منشأة، والعدّاد سنوي أو مستمر."},{"p":"إرسال الاقتراحات والملاحظات","g":"المساعدة والتواصل","u":"feature-requests.html","h":"إرسال الاقتراحات والملاحظات","t":"لديك فكرة لميزة جديدة، أو تحسين على ميزة موجودة؟ أرسلها من داخل «الديوان» إلى مطوّري النظام مباشرة. يصل اقتراحك طلباً (Issue) في صفحة المشروع على GitHub، فيتابعه المطوّر ويصوّت عليه بقية المستخدمين. %%ICON:bulb%%افتح «طلبات المميزات»من داخل النظام %%ICON:pencil%%اكتب طلبكالنوع والعنوان والوصف %%ICON:send%%أرسله من GitHubراجعه ثم اضغط Create %%ICON:thumb%%تابِعه وصوّتردود المطوّر وتصويت المستخدمين الاقتراح يصل إلى مطوّر النظام، لا إلى مالك منشأتك. لطلب صلاحية أو تعديل بيانات داخل منشأتك، تواصل مع مدير النظام عندكم."},{"p":"إرسال الاقتراحات والملاحظات","g":"المساعدة والتواصل","u":"feature-requests.html#قبل-البدء","h":"قبل البدء","t":"حساب GitHub مجاني: يُرسل الطلب باسم حسابك. إن لم يكن لديك حساب فأنشئه من github.com/signup. أي مستخدم يستطيع الإرسال: الصفحة متاحة لكل من يدخل النظام، ولا تحتاج صلاحية خاصة. الطلبات على GitHub عامة يراها الجميع: لا تكتب فيها أسماء عملاء أو مبالغ أو أي بيانات خاصة بمنشأتك."},{"p":"إرسال الاقتراحات والملاحظات","g":"المساعدة والتواصل","u":"feature-requests.html#الخطوة-1-افتح-صفحة-طلبات-المميزات","h":"الخطوة 1: افتح صفحة «طلبات المميزات»","t":"افتحها بإحدى هذه الطرق: من أين؟ ماذا تضغط القائمة الجانبية التحديثات والطلبات ← طلبات المميزات زر «عرض» أعلى الشاشة طلبات المميزات صفحة «أبرز التحديثات» زر «طلبات المميزات» أعلى الصفحة شريط العنوان في المتصفح عنوان النظام وبعده /feature-requests، مثل http://localhost:8000/feature-requests على جهاز المكتب"},{"p":"إرسال الاقتراحات والملاحظات","g":"المساعدة والتواصل","u":"feature-requests.html#الخطوة-2-اكتب-طلبك","h":"الخطوة 2: اكتب طلبك","t":"هكذا تبدو الصفحة في النظام (البيانات للتوضيح فقط): طلب ميزة أو تحسينيصل طلبك إلى مطوّر النظام مباشرة على GitHubأبرز التحديثاتالطلبات المفتوحة والتصويت نوع الطلب *ميزة جديدة الشاشة أو القسمفواتير المبيعاتمثل: فواتير المبيعات، الرواتب عنوان الطلب *تذكير العميل تلقائياً قبل موعد استحقاق الفاتورة الوصف *أريد أن يرسل النظام رسالة تذكير للعميل قبل موعد الاستحقاق بثلاثة أيام، لأننا نتابع ذلك يدوياً اليوم وتفوتنا فواتير كثيرة.ما الذي تريده، ولماذا، وكيف تتخيل عمله؟ عند الإرسال تُفتح صفحة GitHub بالطلب جاهزًا لتراجعه وتؤكد إرساله بحسابك (يلزم حساب GitHub مجاني). يمكن للآخرين التصويت عليه بـ 👍. إرسال إلى المطوّر عبر GitHub املأ الحقول: الحقل ماذا تكتب نوع الطلب (إلزامي) «ميزة جديدة»، أو «تحسين على ميز"},{"p":"إرسال الاقتراحات والملاحظات","g":"المساعدة والتواصل","u":"feature-requests.html#الخطوة-3-راجع-الطلب-في-github-وأرسله","h":"الخطوة 3: راجع الطلب في GitHub وأرسله","t":"تُفتح صفحة GitHub في تبويب جديد، وفيها طلبك جاهزاً: إن طُلب منك الدخول: ادخل بحسابك في GitHub، أو أنشئ حساباً مجانياً. راجع العنوان والوصف. يضيف النظام إلى الوصف تلقائياً نوع الطلب والشاشة ورقم إصدار «الديوان» الذي تستخدمه. أرفق صورة إن أردت: اسحب صورة الشاشة إلى مربع الوصف. اضغط Create (أو Submit new issue) لإرسال الطلب. لا يُرسل شيء قبل أن تضغط زر GitHub. النظام لا يحفظ أي كلمة مرور أو رمز لـ GitHub، ولا يُرسل شيئاً من بيانات منشأتك: الطلب يحتوي ما كتبته ورقم الإصدار فقط. هذا شكل الوصف الذي يصل إلى GitHub: **النوع:** ميزة جديدة **الشاشة أو القسم:** فواتير المبيعات **إصدار الديوان:** 1.5.0 أريد أن يرسل النظام رسالة تذكير للعميل قبل موعد الاستحقاق بثلاثة أيام..."},{"p":"إرسال الاقتراحات والملاحظات","g":"المساعدة والتواصل","u":"feature-requests.html#بعد-الإرسال","h":"بعد الإرسال","t":"المتابعة: يظهر طلبك في قائمة طلبات المشروع، ويصلك بريد من GitHub عند أي رد عليه. التصويت: يصوّت المستخدمون على الطلبات بـ 👍، فيعرف المطوّر أكثرها أهمية. ابحث في القائمة قبل أن تكتب طلباً جديداً: إن وجدت طلبك فصوّت عليه بدل تكراره. عند التنفيذ: تصل الميزة في إصدار جديد إلى نسختك مع التحديث التلقائي، وتظهر في صفحة «أبرز التحديثات» داخل النظام، وعليها نقطة حمراء في القائمة حتى تقرأها."},{"p":"إرسال الاقتراحات والملاحظات","g":"المساعدة والتواصل","u":"feature-requests.html#نصائح-لاقتراح-واضح","h":"نصائح لاقتراح واضح","t":"طلب واحد في كل مرة: فكرتان في طلب واحد يصعب تنفيذهما ومتابعتهما. ابدأ بالمشكلة: ما الذي يصعب عليك اليوم؟ ثم اقترح الحل. كن محدداً: اذكر الشاشة، والخطوات التي تقوم بها الآن، والنتيجة التي تريدها. اختر عنواناً يصف الطلب: «تذكير العميل قبل موعد الاستحقاق» أوضح من «اقتراح» أو «مهم جداً»."},{"p":"إرسال الاقتراحات والملاحظات","g":"المساعدة والتواصل","u":"feature-requests.html#الإبلاغ-عن-خطأ","h":"الإبلاغ عن خطأ","t":"صفحة «طلبات المميزات» للأفكار والتحسينات. إن ظهر لك خطأ، أو توقف شيء عن العمل: صوّر الشاشة التي ظهر فيها الخطأ. افتح طلباً جديداً في صفحة المشروع مباشرة. اكتب ما كنت تفعله قبل الخطأ، ورقم إصدار «الديوان» (يظهر أعلى صفحة «أبرز التحديثات»)، وأرفق الصورة."},{"p":"إرسال الاقتراحات والملاحظات","g":"المساعدة والتواصل","u":"feature-requests.html#حل-المشكلات","h":"حل المشكلات","t":"المشكلة الحل لم تُفتح صفحة GitHub بعد الضغط على الزر المتصفح منع فتح نافذة جديدة. اسمح بالنوافذ المنبثقة لعنوان النظام، ثم اضغط الزر مرة أخرى. GitHub يطلب تسجيل الدخول الإرسال يحتاج حساباً في GitHub. ادخل أو أنشئ حساباً مجانياً. إن وجدت الطلب فارغاً بعد الدخول، فارجع إلى «طلبات المميزات» واضغط الإرسال من جديد. ظهر خطأ في GitHub والوصف طويل جداً نص الطلب يُنقل إلى GitHub داخل الرابط، وللرابط حد أقصى. اختصر الوصف في النظام، وأكمل التفاصيل في GitHub قبل الإرسال. لا أجد «طلبات المميزات» في القائمة افتح مجموعة «التحديثات والطلبات» في آخر القائمة الجانبية، أو استعمل زر «عرض» أعلى الشاشة."}];
